\label{thm:kuperberg-lalin-trace-average}
Let $A\in \mathbb{F}_q[T]$ be a monic polynomial of degree $n$, let
$0\leq h \leq n-2$, and define
\begin{equation*}
   \mathcal{N}^{U}_{0,\Lambda^{*k}_q}(A;h)
   :=
   \sum_{\substack{f\ \mathrm{monic}\\ |f-A|\leq q^h\\ f(0)\neq 0}}
  \Lambda^{*k}_q(f).
\end{equation*}
Assume $k\leq n$. Then, as $q\to\infty$,
\begin{equation*}
   \left\langle \mathcal{N}^{U}_{0,\Lambda^{*k}_q}\right\rangle
   \sim
   q^{h+1}\binom{n-1}{k-1},
\end{equation*}
and
\begin{equation*}
   \frac{1}{q^n}
   \sum_{A\in\mathcal{M}_n}
   \left|
      \mathcal{N}^{U}_{0,\Lambda^{*k}_q}(A;h)
      -\left\langle \mathcal{N}^{U}_{0,\Lambda^{*k}_q}\right\rangle
   \right|^2
   \sim
   q^{h+1}
   \int_{U(n-h-2)}
   \left|
      \sum_{\substack{j_1+\cdots+j_k=n\\ 1\leq j_1,\ldots,j_k}}
      \operatorname{Tr}(U^{j_1})\cdots \operatorname{Tr}(U^{j_k})
   \right|^2
   dU.
\end{equation*}

\label{thm:leading-volume}
Let $k\geq1$ be an integer, and let
$\mathcal K\subset(0,\infty)$ be compact. For $c\in\mathcal K$, put
$n=\lfloor cN\rfloor$. Then, uniformly for $c\in\mathcal K$,
\begin{equation}\label{eq:Ik-asymptotic}
I_k(n;N)
=
\delta_k(c)N^{2k-1}
+
O_{k,\mathcal K}(N^{2k-2}),
\end{equation}
where
\begin{equation}\label{eq:delta-def}
\delta_k(c)
=
\sum_{r=1}^{\lfloor\sqrt{k}\rfloor}
\frac{1}{(r!)^2}
\int_{\substack{x_i\geq0\\0\leq y_i\leq1}}
\Phi_{k,r}(\mathbf x,\mathbf y)^2
\,
\delta\left(
\sum_{i=1}^r(x_i+y_i)-c
\right)
\prod_{i=1}^r d x_i \, d y_i.
\end{equation}
Here, $\Phi_{k,r}$ is as defined in \eqref{eq:Phi-def}.

\label{thm:delta-cycle-formula}
Let $k\geq1$ be an integer. For every $c>0$,
\begin{equation}
\label{eq:delta-cycle-final}
\delta_k(c)
=
\sum_{(\pi,\sigma)\in\mathfrak J_k}
\operatorname{sgn}(\sigma)
\int_{\mathbb R_{>0}^{2k}}
\delta\!\left(\sum_{i=1}^{k}u_i-c\right)
\prod_{\mathcal C\in\operatorname{Cyc}(\sigma)}
\mathcal W_{\mathcal C}(\mathbf u,\mathbf v)
\,d\mathbf u\,d\mathbf v,
\end{equation}
with the notation as in
\eqref{eq:block-permutation-set}--\eqref{eq:cycle-kernel}. For every compact $\mathcal K\subset(0,\infty)$, \eqref{eq:Ik-asymptotic} holds uniformly for
$c\in\mathcal K$ when
$n=\lfloor cN\rfloor$, with $\delta_k(c)$ given by
\eqref{eq:delta-cycle-final} and an error
$O_{k,\mathcal K}(N^{2k-2})$.

\label{thm:lauricella}
Let $k\geq1$ be an integer. For $1\leq r\leq\lfloor\sqrt{k}\rfloor$ and $\alpha,\beta\in\mathbb Z_{\geq0}^r$, set $d_{\alpha,r}
 =|\alpha|+r-1$ and let $\mathbf1_r=(1,\ldots,1)$ with length $r$. For $c>0$,
\begin{align*}
 \delta_k(c)
 &=
 \sum_{r=1}^{\lfloor\sqrt{k}\rfloor}\frac{1}{(r!)^2}
 \sum_{\substack{\alpha,\beta\in\mathbb Z_{\geq0}^r\\
                  |\alpha|+|\beta|=2(k-r)}}
 \alpha!\beta!\,p_{\alpha,\beta}^{(k,r)} \\& \hspace{1.8in} \times
 \sum_{S\subseteq[r]}(-1)^{|S|}
 \sum_{\substack{0\leq q_i\leq\beta_i \\ i\in S}}
 \frac{(c-|S|)_+^{\,2k-1-\sum_{i\in S}q_i}}
 {\left(2k-1-\sum_{i\in S}q_i\right)!
  \displaystyle\prod_{i\in S}q_i!}.
\end{align*}
On the range
$c\geq\lfloor\sqrt{k}\rfloor$, this becomes
\begin{align}
 \label{eq:delta-Lauricella}
 \delta_k(c)
 &=
 \sum_{r=1}^{\lfloor\sqrt{k}\rfloor}\frac{1}{(r!)^2}
 \sum_{\substack{\alpha,\beta\in\mathbb Z_{\geq0}^r\\
                  |\alpha|+|\beta|=2(k-r)}}
 \frac{\alpha!\,p_{\alpha,\beta}^{(k,r)}
       c^{d_{\alpha,r}}}
 {d_{\alpha,r}!\displaystyle\prod_{i=1}^r(\beta_i+1)}
 F_A^{(r)}
 \left(
  -d_{\alpha,r};
  \beta+\mathbf1_r;
  \beta+2\mathbf1_r;
  c^{-1}\mathbf1_r
 \right).
\end{align}
Here, $F_A^{(r)}$ is the Lauricella function defined in \eqref{eq:FA-definition} and $p_{\alpha,\beta}^{(k,r)}$ in \eqref{eq:p-definition}. In the above, $\alpha!=\prod_i\alpha_i!$, $\beta!=\prod_i\beta_i!$ and empty products are interpreted as $1$.

\label{thm:two-centre}
For an integer $k\geq1$ and $c>0$,
\begin{equation}
\label{eq:two-centre-final-formula}
 \delta_k(c)
 =
 (-1)^k\mathcal L^{-1}_{s\to c}
 \left[
 \left.
 s^{-k}\left(1+\frac{\partial_u}{s}\right)^k
 \partial_v^kD_k(0;s,u,v)
 \right|_{u=v=0}
 \right],
\end{equation}
where $D_k$ is defined using \eqref{eq:two-centre-X}-\eqref{eq:two-centre-D}, and
$\mathcal L^{-1}_{s\to c}$ as defined by
\eqref{eq:two-centre-Laplace-definition}.

\label{thm:davenport}
Let $S\subset\mathbb R^D$ be a convex region contained in a closed ball of
radius $\rho$. Then
\begin{equation}
\label{eq:davenport}
 \#(S\cap\mathbb Z^D)
 =
 \operatorname{vol}_D(S)
 +O_D(\rho^{D-1}+1).
\end{equation}

\label{lem:weighted-lattice-volume}
Let $D\geq1$ be an integer, and let $\{V_t\}_{t\in T}$ be a family of
$D$-dimensional convex polytopes in $\mathbb R^D$, contained in a common
compact set and having a uniformly bounded number of facets. Let $U$ be a
fixed, open neighbourhood of this compact set, and let
$\mathcal P_t\in C^1(U)$ satisfy
\begin{equation*}
 \sup_{t\in T}\|\mathcal P_t\|_{C^1(U)}<\infty.
\end{equation*}
Then, as $N\to\infty$, uniformly for $t\in T$,
\begin{equation}
\label{eq:weighted-lattice-volume}
 \sum_{\mathbf m\in NV_t\cap\mathbb Z^D}
 \mathcal P_t(\mathbf m/N)
 =
 N^D\int_{V_t}\mathcal P_t(\mathbf z)\,d\mathbf z
 +O(N^{D-1}).
\end{equation}
The same estimate remains valid if the lattice points lying on any collection of facets of $NV_t$ are omitted from the sum.

\label{lem:weighted-lattice-count}
Let $k,n,N \geq 1$ be integers. For a partition $\lambda\vdash n$, let $\chi^\lambda_\mu$ denote the
irreducible character of $S_n$ indexed by $\lambda$, evaluated on the
conjugacy class of cycle type $\mu$.  If
$\nu=(\nu_1,\ldots,\nu_k)$ is an ordered composition of $n$, write
$\chi^\lambda_\nu$ for the corresponding character value and put
\begin{equation}
\label{eq:Ak-lambda-def}
 A_k(\lambda)
 :=
 \sum_{\substack{\nu_1+\cdots+\nu_k=n\\ \nu_i\geq1}}
 \chi^\lambda_\nu.
\end{equation}
For an integer $r\geq1$, define the Frobenius coordinate set
\begin{equation}
\label{eq:Frobenius-coordinate-set}
 \mathcal F_r(n,N)
 :=
 \left\{
 (\mathbf a,\mathbf b)\in(\mathbb Z_{\geq0}^r)^2:
 \begin{aligned}
  &a_1>\cdots>a_r,\qquad N>b_1>\cdots>b_r,\\
  &\sum_{i=1}^r(a_i+b_i)=n-r
 \end{aligned}
 \right\}.
\end{equation}
For $(\mathbf a,\mathbf b)\in\mathcal F_r(n,N)$, write
$A_k(\mathbf a,\mathbf b):=A_k(\lambda)$, where
$\lambda=(a_1,\ldots,a_r\mid b_1,\ldots,b_r)$ is the corresponding
partition. Then
\begin{equation}
\label{eq:Ik-lattice-count}
 I_k(n;N)
 =
 \sum_{r\geq1}
 \sum_{(\mathbf a,\mathbf b)\in\mathcal F_r(n,N)}
 A_k(\mathbf a,\mathbf b)^2.
\end{equation}
Only finitely many of the sets $\mathcal F_r(n,N)$ are non-empty.

By definition,
\begin{equation*}
 I_{k}(n;N) = \int_{U(N)}|F_{k,n}(U)|^2 dU, \qquad F_{k,n}(U)
:=\sum_{\substack{\nu_1+\cdots+\nu_k=n\\\nu_i\geq1}}
   \operatorname{Tr}(U^{\nu_1})\cdots\operatorname{Tr}(U^{\nu_k}).
\end{equation*}
Using \eqref{eq:power-sum-trace}, $F_{k,n}(U)$ can be written as a sum of products of power-sum
symmetric functions at the eigenvalues of $U$. By \eqref{eq:frobenius-character-formula}, we express each power-sum product $p_\mu = p_{\mu_1} \cdots p_{\mu_k}$ in the Schur basis. Applying it to every
ordered composition $\nu=(\nu_1,\ldots,\nu_k)$ of $n$ gives
\begin{align}
 F_{k,n}(U)
 &=\sum_{\substack{\nu_1+\cdots+\nu_k=n\\\nu_i\geq1}}
   p_{\nu_1}(U)\cdots p_{\nu_k}(U)\nonumber\\
 &=\sum_{\substack{\nu_1+\cdots+\nu_k=n\\\nu_i\geq1}}
   \sum_{\lambda\vdash n}\chi^\lambda_\nu s_\lambda(U)\nonumber\\
 &=\sum_{\lambda\vdash n}A_k(\lambda)s_\lambda(U).
 \label{eq:F-Schur-expansion}
\end{align}
By definition, $I_k(n;N)$ is the Haar integral of $|F_{k,n}(U)|^2$.
Substituting \eqref{eq:F-Schur-expansion} and applying
\eqref{eq:schur-orthogonality} eliminates all cross terms.  Since the
characters of $S_n$ are real-valued, $|A_k(\lambda)|^2=A_k(\lambda)^2$,
and therefore
\begin{equation}\label{eq:Ik-partition-sum}
 I_k(n;N)
 =\sum_{\substack{\lambda\vdash n\\\ell(\lambda)\leq N}}
 A_k(\lambda)^2.
\end{equation}
If $\lambda$ has Frobenius rank $r$, the identities
\eqref{eq:frobenius-size-length} show that the conditions in
\eqref{eq:Ik-partition-sum} are precisely those defining
$\mathcal F_r(n,N)$.  Every partition has a unique Frobenius rank and unique
Frobenius coordinates, so grouping \eqref{eq:Ik-partition-sum} by rank proves
\eqref{eq:Ik-lattice-count}.  The sum is finite: the strict inequalities in
the Frobenius coordinates give $a_i,b_i\geq r-i$, and hence
$|\lambda|\geq r^2$.

Let $k \geq 1$ be a fixed integer, and fix a non-empty compact set $\mathcal K\subset(0,\infty)$ for which we set $c^+ := \max \mathcal{K}$. For an integer $N \geq 1$ and $c\in \mathcal K$, put $n=\lfloor cN\rfloor$; all estimates below are uniform for such $c$. We begin by
identifying the leading polynomial term from the character weight and then
use Lemma~\ref{lem:weighted-lattice-volume} to replace the weighted lattice
sum by a volume, before removing the ordering constraints by symmetry.

\subsubsection{The leading character weight}
Using the Cauchy identity, we will first obtain an expression that sums over partitions of all sizes and then extract its degree-$n$ part, which we then compare with the expansion
\eqref{eq:F-Schur-expansion}. For each $u\in\mathbb C$, we define the specialisation $\mathcal A_u$ by
\begin{equation}
\label{eq:virtual-alphabet}
 p_j(\mathcal A_u)=ju,
 \qquad j\geq1.
\end{equation}
As noted in Subsection~\ref{subseq:symmetric-functions}, these values determine
$f(\mathcal A_u)$ for every symmetric function $f$. Moreover, since $f$ is a
polynomial in finitely many power sums, $f(\mathcal A_u)$ is a polynomial in
the parameter $u$. For two sets of variables $X$ and $Y$, the Cauchy identity in
power-sum form is
\begin{equation}
\label{eq:cauchy-general}
 \sum_\lambda s_\lambda(X)s_\lambda(Y)
 =
 \exp\!\left(
  \sum_{j\geq1}\frac{p_j(X)p_j(Y)}{j}
 \right).
\end{equation}
We interpret \eqref{eq:cauchy-general}, and the specialised identities
derived from it, one homogeneous degree in $Y$ at a time. In each fixed
degree only finitely many terms occur; after applying $\mathcal A_u$,
both sides are polynomials in $u$, so taking the coefficient of $u^k$
is legitimate.

Applying $\mathcal A_u$ to the symmetric functions in $X$ and using
\eqref{eq:virtual-alphabet}, we obtain
\begin{align*}
 \sum_\lambda s_\lambda(\mathcal A_u)s_\lambda(Y)
 &=
 \exp\!\left(
  \sum_{j\geq1}\frac{p_j(\mathcal A_u)p_j(Y)}{j}
 \right)=
 \exp\!\left(u\sum_{j\geq1}p_j(Y)\right).
\end{align*}
We suppress the variables $Y$ from now on, writing $p_j=p_j(Y)$ and
$s_\lambda=s_\lambda(Y)$. For a non-empty partition $\lambda$, we can write
\begin{equation}
\label{eq:c-expansion}
 s_\lambda(\mathcal A_u)
 =\sum_{m\geq1}c_m(\lambda)u^m.
\end{equation}
As $s_{\varnothing}(\mathcal A_u)=1$ and
$s_\lambda(\mathcal A_0)=0$ for $\lambda\neq\varnothing$, the positive
powers of $u$ arise only from non-empty partitions. Taking the coefficient of $u^k$, with $k\geq1$, in the specialised Cauchy
identity above gives
\begin{equation*}
 \sum_{\lambda, \, |\lambda| \geq 1} c_k(\lambda)s_\lambda
 =
 \frac{1}{k!}\biggl(\sum_{j\geq1}p_j\biggr)^k.
\end{equation*}
Here $p_j$ has degree $j$, so
$p_{\nu_1}\cdots p_{\nu_k}$ has degree
$\nu_1+\cdots+\nu_k$.  Similarly, $s_\lambda$ has degree
$|\lambda|$. It follows that the terms of degree $n$ are
\begin{align*}
 \sum_{\lambda\vdash n}c_k(\lambda)s_\lambda
 &=
 \frac{1}{k!}
 \sum_{\substack{\nu_1+\cdots+\nu_k=n\\ \nu_i\geq1}}
 p_{\nu_1}\cdots p_{\nu_k}=
 \frac{1}{k!}
 \sum_{\lambda\vdash n}A_k(\lambda)s_\lambda,
\end{align*}
where the second equality follows from
\eqref{eq:frobenius-character-formula} and the definition
\eqref{eq:Ak-lambda-def} of $A_k(\lambda)$. As the Schur functions are linearly independent, their coefficients on the two sides are equal. Therefore
\begin{equation}
\label{eq:Ak-specialized-Schur}
 c_k(\lambda)=\frac{A_k(\lambda)}{k!},
 \qquad \lambda\vdash n.
\end{equation}
We first evaluate $c_k(\lambda)$ when $\lambda$ is a hook. This is not a restriction to a special class of partitions in the final argument; hooks are considered first as they serve as building blocks for Schur functions of arbitrary partitions. Namely, if a partition $\lambda = (a_1, \ldots, a_r | b_1, \ldots,b_r)$ has Frobenius rank $r$, then  Giambelli's
formula \cite[Ex.~9, p.~47]{kn:macdonald1995} states
\begin{equation}
\label{eq:frobenius-gambelli}
 s_\lambda
 =\det_{1\leq i,j\leq r}
   \bigl[s_{(a_i\mid b_j)}\bigr],
\end{equation}
where
$(a\mid b)$ is the Frobenius notation for a hook as introduced in \eqref{eq:frob-hook}.
Thus, after computing the specialised hook functions
$s_{(a\mid b)}(\mathcal A_u)$, we will return to a general partition,
apply the specialisation entrywise to this determinant, and then extract the
coefficient of $u^k$. 

Let $h_q$ and $e_q$ denote the complete and elementary symmetric
functions, and define their generating series by
\begin{align*}
 H(x):=\sum_{q\geq0}h_qx^q
      =\exp \, \biggl(\sum_{j\geq1}\frac{p_jx^j}{j}\biggr), \qquad
 E(y):=\sum_{q\geq0}e_qy^q
      =\exp \, \biggl(\sum_{j\geq1}
        \frac{(-1)^{j-1}p_jy^j}{j}\biggr).
\end{align*}
These two identities follow from equations 2.10 and 2.10' in \cite{kn:macdonald1995}. For a hook $(a\mid b)$, the Jacobi--Trudi formula gives
\begin{equation*}
 s_{(a\mid b)}
 =
 \sum_{j=0}^{b}(-1)^j h_{a+1+j}e_{b-j}.
\end{equation*}
The Schur functions indexed by hooks therefore satisfy
\begin{align*}
 \sum_{a,b\geq0}s_{(a\mid b)}x^ay^b
 &=
 \sum_{a,b\geq0}\sum_{j=0}^{b}
 (-1)^j h_{a+1+j}e_{b-j}x^ay^b\\
 &=
 E(y)\sum_{a,j\geq0}
 (-1)^j h_{a+1+j}x^ay^j\\
 &=
 E(y)\frac{H(x)-H(-y)}{x+y}.
\end{align*}
As $H(-y)E(y)=1$, this becomes
\begin{equation}
\label{eq:hook-generating-identity}
 \sum_{a,b\geq0}s_{(a\mid b)}x^ay^b
 =
 \frac{H(x)E(y)-1}{x+y}.
\end{equation} 
Next, we apply the specialisation \eqref{eq:virtual-alphabet} to the
generating series $H(x)$ and $E(y)$. Define $H_{\mathcal A_u}(x) := \sum_{q\geq 0}h_q(\mathcal A_u)x^q$ and $E_{\mathcal A_u}(y) := \sum_{q\geq 0}e_q(\mathcal A_u)y^q$. We can write both as
\begin{align*}
 H_{\mathcal A_u}(x)
 &=\exp \biggl(
   \sum_{j\geq1}\frac{p_j(\mathcal A_u)x^j}{j}
  \biggr)
  =\exp \biggl(u\sum_{j\geq1}x^j\biggr)
  =\exp \biggl(\frac{ux}{1-x}\biggr),\\
 E_{\mathcal A_u}(y)
 &=\exp\!\biggl(
   \sum_{j\geq1}\frac{(-1)^{j-1}p_j(\mathcal A_u)y^j}{j}
  \biggr)
  =\exp \biggl(u\sum_{j\geq1}(-1)^{j-1}y^j\biggr)
  =\exp \biggl(\frac{uy}{1+y}\biggr).
\end{align*}
Substituting these expressions into
\eqref{eq:hook-generating-identity}, we obtain
\begin{align}
\label{eq:hook-series}
 \sum_{a,b\geq0}s_{(a\mid b)}(\mathcal A_u)x^ay^b
 &=\frac{1}{x+y}
   \left[
    \exp\!\left(
      u\left(\frac{x}{1-x}+\frac{y}{1+y}\right)
    \right)-1
   \right]\\ \nonumber
 &=\frac{1}{x+y}
   \left[
    \exp\!\left(
      u\frac{x+y}{(1-x)(1+y)}
    \right)-1
   \right]\\
 &=\sum_{m\geq1}
   \frac{(x+y)^{m-1}}{m!(1-x)^m(1+y)^m}u^m. \nonumber
\end{align}
We also arrive at a separate expression for the series in \eqref{eq:hook-series} by comparing with the coefficients in \eqref{eq:c-expansion}. For each hook $(a\mid b)$, define $\theta_m(a,b)$ by
\begin{equation}
\label{eq:theta-expansion}
 s_{(a\mid b)}(\mathcal A_u)
 =\sum_{m\geq1}\theta_m(a,b)u^m,
\end{equation}
and thus $\theta_m(a,b)=c_m((a\mid b))$. In particular, for a hook of
size $a+b+1=n$, \eqref{eq:Ak-specialized-Schur} gives
\begin{equation*}
A_k((a\mid b))=k!\,\theta_k(a,b).
\end{equation*}
Using \eqref{eq:theta-expansion}, we can write
\begin{align*}
 \sum_{a,b\geq0}s_{(a\mid b)}(\mathcal A_u)x^ay^b
 &=\sum_{a,b\geq0}\sum_{m\geq1}
   \theta_m(a,b)u^mx^ay^b=\sum_{m\geq1}
   \biggl( \,
    \sum_{a,b\geq0}\theta_m(a,b)x^ay^b
   \biggr)u^m.
\end{align*}
The coefficients of $u^m$ in these two expressions must agree.
Therefore
\begin{equation}
\label{eq:theta-generating-function}
 \sum_{a,b\geq0}\theta_m(a,b)x^ay^b
 =
 \frac{(x+y)^{m-1}}{m!(1-x)^m(1+y)^m},
 \qquad m\geq1.
\end{equation}
We now set $d=m-1$ and expand the factors on the right-hand side of
\eqref{eq:theta-generating-function},
\begin{align*}
 (x+y)^d
 &=\sum_{j=0}^{d}\binom{d}{j}x^{d-j}y^j, \qquad
 (1-x)^{-m}
 =\sum_{r\geq0}\binom{r+d}{d}x^r, 
\end{align*}
and $ (1+y)^{-m}$ similarly. For a fixed $j$, the term $x^ay^b$ is obtained by taking
$r=a-d+j$ and $s=b-j$. Hence
\begin{equation}
\label{eq:Qm-exact}
 (-1)^b\theta_m(a,b)
 =
 \frac1{m!}
 \sum_{j=0}^{d}(-1)^j\binom{d}{j}
 \binom{a+j}{d}
 \binom{b+d-j}{d}.
\end{equation}
Here, as usual, a binomial coefficient is zero when its upper entry is a
non-negative integer smaller than its lower entry. Denote the polynomial on
the right-hand side of \eqref{eq:Qm-exact} by \(Q_m(a,b)\), so that
\begin{equation}
\label{eq:theta-polynomial}
 \theta_m(a,b)=(-1)^bQ_m(a,b).
\end{equation}
We now establish the bound $\deg Q_m\leq m-1$ and identify all terms of
$Q_m$ of total degree $m-1$ in the variables $a$ and $b$. We use the fact that
\begin{equation*}
 \sum_{j=0}^{d}(-1)^j\binom{d}{j}f(j)=0
\end{equation*}
whenever $f$ is a polynomial in $j$ of degree less than $d$. Consider
the coefficient of $a^pb^q$ in \eqref{eq:Qm-exact}. The coefficient of
$a^p$ in $\binom{a+j}{d}$ has degree at most $d-p$ as a polynomial in
$j$, while the coefficient of $b^q$ in $\binom{b+d-j}{d}$ has degree at
most $d-q$. Their product therefore has degree at most
$2d-p-q$ in $j$. If $p+q>d$, this degree is less than $d$, and the
alternating sum vanishes. Thus
\begin{equation*}
 \deg Q_m\leq d=m-1.
\end{equation*}

Focusing on the terms of $Q_m$ with total degree $d$, the case
$d=0$ is immediate, so assume $d\geq1$ and fix $p,q\geq0$ with
$p+q=d$. When viewed as a polynomial in $j$, the coefficient of $a^p$ in
$\binom{a+j}{d}$ has highest-power term
\begin{equation*}
 \frac{1}{d!}\binom{d}{p}j^{d-p},
\end{equation*}
while the coefficient of $b^q$ in $\binom{b+d-j}{d}$ has highest-power term
\begin{equation*}
 \frac{(-1)^{d-q}}{d!}\binom{d}{q}j^{d-q}.
\end{equation*}
Since $p+q=d$, their product has highest power $j^d$. Using the alternating
binomial identity
\begin{equation*}
 \sum_{j=0}^{d}(-1)^j\binom{d}{j}j^d
 =(-1)^d d!,
\end{equation*}
together with $\binom{d}{p}=\binom{d}{q}$, and collecting the resulting
monomials over all $p+q=d$, we obtain the entire highest-degree part of
$Q_m$. Recalling that $d=m-1$, we denote it by
\begin{equation}
\label{eq:Qm-leading}
 \Theta_m(a,b)
 =
 \frac{1}{m!(m-1)!}
 \sum_{j=0}^{m-1}(-1)^j\binom{m-1}{j}^{\!2}
 a^{m-1-j}b^j.
\end{equation}
Thus $\Theta_m$ consists precisely of the terms of $Q_m$ having total degree
$m-1$. By substituting $n=m-1$, $x=a$ and $y=b$ into the polynomial identity \eqref{eq:Legendre-homogeneous-expansion}, we may express $\Theta_m$ in terms of a Legendre polynomial, as stated in \eqref{eq:Theta-legendre-def}.

This separation is useful because the terms in $\Theta_m$ determine the
leading order when the Frobenius coordinates are scaled by $N$. The remainder
$Q_m-\Theta_m$ has degree at most $m-2$ since
$\Theta_m$ is precisely the degree-$(m-1)$ part of $Q_m$.
For $(\mathbf a,\mathbf b)\in\mathcal F_r(n,N)$, the Frobenius coordinates
satisfy
\begin{equation*}
 0\leq \frac{a_i}{N}\leq c^+,
 \qquad
 0\leq \frac{b_j}{N}<1.
\end{equation*}
Thus the scaled arguments $(a_i/N,b_j/N)$ remain in a fixed compact region.
It follows uniformly in $i$ and $j$ that
\begin{equation}
\label{eq:theta-leading}
 \theta_m(a_i,b_j)
 =
 (-1)^{b_j}\left(
  N^{m-1}\Theta_m(a_i/N,b_j/N)
  +O_{m,\mathcal K}(N^{m-2})
 \right),
\end{equation}
with no error term when $m=1$.
We now use the previous hook calculations to recover the character weight for
$(\mathbf a,\mathbf b)\in\mathcal F_r(n,N)$, with $\lambda=(a_1,\ldots,a_r\mid b_1,\ldots,b_r)$
denoting the corresponding partition. Using \eqref{eq:frobenius-gambelli}, and applying the
specialisation $\mathcal A_u$ entrywise, gives
\begin{equation*}
 s_\lambda(\mathcal A_u)
 =
 \det_{1\leq i,j\leq r}
 \bigl[s_{(a_i\mid b_j)}(\mathcal A_u)\bigr]
 =
 \det_{1\leq i,j\leq r}
 \biggl[
   \sum_{m\geq1}\theta_m(a_i,b_j)u^m
 \biggr].
\end{equation*}
By multilinearity of the determinant in its rows, the coefficient of $u^k$
is therefore
\begin{equation*}
 c_k(\lambda)
 =
\sum_{\substack{m_1+\cdots+m_r=k\\m_i\geq1}}
 \det_{1\leq i,j\leq r}
 \bigl[\theta_{m_i}(a_i,b_j)\bigr].
\end{equation*}
Using \eqref{eq:theta-polynomial}, each entry in column $j$ contributes the
factor $(-1)^{b_j}$. Factoring these signs from the columns gives
\begin{equation*}
 c_k(\lambda)
 =
 (-1)^{b_1+\cdots+b_r}
 \sum_{\substack{m_1+\cdots+m_r=k\\m_i\geq1}}
 \det_{1\leq i,j\leq r}
 \bigl[Q_{m_i}(a_i,b_j)\bigr].
\end{equation*}
From \eqref{eq:Ak-specialized-Schur}, we have 
$A_k(\lambda)=k!\,c_k(\lambda)$ and, using
$A_k(\mathbf a,\mathbf b):=A_k(\lambda)$ for
$(\mathbf a,\mathbf b)\in\mathcal F_r(n,N)$, we obtain
\begin{equation}
\label{eq:Ak-determinant}
 A_k(\mathbf a,\mathbf b)
 =
 (-1)^{b_1+\cdots+b_r}k!
 \sum_{\substack{m_1+\cdots+m_r=k\\m_i\geq1}}
 \det_{1\leq i,j\leq r}
 \bigl[Q_{m_i}(a_i,b_j)\bigr].
\end{equation}
In particular, the sum is empty when $k<r$, so
$A_k(\mathbf a,\mathbf b)=0$ in that case. We rename the sum above with the $k!$ prefactor as $\mathcal Q_{k,r}(\mathbf a,\mathbf b)$, which then gives
\begin{equation*}
  A_k(\mathbf a,\mathbf b)
 =
 (-1)^{b_1+\cdots+b_r} \mathcal Q_{k,r}(\mathbf a,\mathbf b).
\end{equation*}
A polynomial is alternating in a set of variables if interchanging two of them
changes its sign. Swapping two $b$-variables swaps two determinant columns.
Swapping $a_i$ and $a_j$, and then relabelling $m_i$ and $m_j$ in the
composition sum, swaps the corresponding rows. Thus
$\mathcal Q_{k,r}$ is alternating separately in the $a$-variables and the
$b$-variables. Every
alternating polynomial is divisible by the corresponding Vandermonde
polynomial, so
\begin{equation*}
 \Delta(\mathbf a)\Delta(\mathbf b)
 \mid \mathcal Q_{k,r}(\mathbf a,\mathbf b),
 \qquad
 \Delta(\mathbf a):=\prod_{i<j}(a_j-a_i),
 \quad
 \Delta(\mathbf b):=\prod_{i<j}(b_j-b_i).
\end{equation*}
The product $\Delta(\mathbf a)\Delta(\mathbf b)$ has total degree
$r(r-1)$.  On the other hand, each term in
\eqref{eq:Ak-determinant} has degree at most
\begin{equation*}
 \sum_{i=1}^r(m_i-1)=k-r.
\end{equation*}
If $r^2>k$, then $k-r<r(r-1)$, so the divisibility forces
\begin{equation}
\label{eq:rank-cutoff}
 A_k(\mathbf a,\mathbf b)=0.
\end{equation}
Thus only ranks $r\leq R:=\lfloor\sqrt{k}\rfloor$ contribute. Because $\mathcal K$ is a non-empty compact subset of $(0,\infty)$, it has
a positive minimum. As $R$ depends only on $k$, we may henceforth assume
that $N$ is sufficiently large that
$n=\lfloor cN\rfloor\geq R+1$ uniformly for $c\in\mathcal K$. Therefore, $n-r\geq1$ for every $1\leq r\leq R$.

Replacing each $Q_{m_i}$ in \eqref{eq:Ak-determinant} by its leading part
\eqref{eq:Qm-leading} gives
\begin{equation}
\label{eq:A-leading}
 A_k(\mathbf a,\mathbf b)
 =
 (-1)^{b_1+\cdots+b_r}N^{k-r}
 \Phi_{k,r}(\mathbf a/N,\mathbf b/N)
 +O_{k,\mathcal K}(N^{k-r-1}),
\end{equation}
where
\begin{equation*}
 \Phi_{k,r}(\mathbf x,\mathbf y)
 =
 k!\sum_{\substack{m_1+\cdots+m_r=k\\m_i\geq1}}
 \det_{1\leq i,j\leq r}
 \bigl[\Theta_{m_i}(x_i,y_j)\bigr].
\end{equation*}
By squaring \eqref{eq:A-leading}, we have
\begin{equation}
\label{eq:A-square-leading}
 A_k(\mathbf a,\mathbf b)^2
 =
 N^{2k-2r}\Phi_{k,r}(\mathbf a/N,\mathbf b/N)^2
 +O_{k,\mathcal K}(N^{2k-2r-1}).
\end{equation}
Recall from \eqref{eq:Ik-lattice-count} that
\begin{equation*}
 I_k(n;N)
 =
 \sum_{r\geq1}
 \sum_{(\mathbf a,\mathbf b)\in\mathcal F_r(n,N)}
 A_k(\mathbf a,\mathbf b)^2.
\end{equation*}
Thus, to sum the pointwise error in \eqref{eq:A-square-leading}, we need an
upper bound for the number of points in $\mathcal F_r(n,N)$ for each fixed
$r$. Dropping both the ordering conditions and the
upper bound $b_1<N$ leaves non-negative integers
$a_1,\ldots,a_r,b_1,\ldots,b_r$ satisfying only $ \sum_{i=1}^r(a_i+b_i)=n-r$. The number of such $2r$-tuples is
\begin{equation*}
 \binom{(n-r)+2r-1}{2r-1}
 =
 \binom{n+r-1}{2r-1},
\end{equation*}
since this counts the ways of distributing $n-r$ identical units among
$2r$ non-negative coordinates. Hence
\begin{equation*}
 \#\mathcal F_r(n,N)
 \leq
 \binom{n+r-1}{2r-1}
 =
 O_{r,\mathcal K}(N^{2r-1}),
\end{equation*}
where we used $n=\lfloor cN\rfloor$ with $c\in\mathcal K$.

For fixed $r$, the error in \eqref{eq:A-square-leading} is therefore summed
over at most $O_{r,\mathcal K}(N^{2r-1})$ points, giving a total contribution
\begin{equation*}
 O_{k,\mathcal K}(N^{2k-2r-1})
 \,O_{r,\mathcal K}(N^{2r-1})
 =
 O_{k,r,\mathcal K}(N^{2k-2}).
\end{equation*}
The rank cutoff restricts the outer sum to
$r\leq R$, so only finitely many values of $r$
occur. Substituting \eqref{eq:A-square-leading} into
\eqref{eq:Ik-lattice-count} therefore yields
\begin{equation}
\label{eq:Ik-after-leading-weight}
 I_k(n;N)
 =
 \sum_{r=1}^{R}N^{2k-2r}
 \sum_{(\mathbf a,\mathbf b)\in\mathcal F_r(n,N)}
 \Phi_{k,r}(\mathbf a/N,\mathbf b/N)^2
 +O_{k,\mathcal K}(N^{2k-2}).
\end{equation}

\subsubsection{Replacing the lattice sum by a volume}
We now aim to represent the count in \eqref{eq:Ik-after-leading-weight} by an
integral at leading order. For fixed $r$, the Frobenius coordinates satisfy
\begin{equation*}
 \sum_{i=1}^r(a_i+b_i)=n-r.
\end{equation*}
After scaling $a_i=Nx_i$ and $b_i=Ny_i$, this becomes
\begin{equation}
\label{eq:scaled-size}
 \sum_{i=1}^r(x_i+y_i)=d_{r,N}(c),
 \qquad
 d_{r,N}(c):=\frac{n-r}{N}.
\end{equation}
Thus the $2r$ scaled coordinates satisfy one linear constraint, leaving
$2r-1$ independent variables. By our restriction to sufficiently large $N$, the parameter $d_{r,N}(c)$ is positive
for every $1\leq r\leq R$. Since $n=\lfloor cN\rfloor$,
\begin{equation*}
 d_{r,N}(c)
 =\frac{n-r}{N}
 =c+O_r(N^{-1}),
\end{equation*}
so $d_{r,N}(c)\to c$ as $N\to\infty$.

It is convenient to introduce a general
parameter $d>0$ to describe both the finite-$N$ region, where $d=d_{r,N}(c)$, and its
limiting form, where $d=c$. To apply
Lemma~\ref{lem:weighted-lattice-volume} in these independent coordinates, we
eliminate $y_r$. For $d>0$, let
$V_{r,d}\subset\mathbb R^{2r-1}$ have coordinates
$(x_1,\ldots,x_r,y_1,\ldots,y_{r-1})$, set
\begin{equation}
\label{eq:yr-eliminate}
 y_r
 =
 d-\sum_{i=1}^r x_i-\sum_{i=1}^{r-1}y_i,
\end{equation}
and impose
\begin{equation}
\label{eq:Vrd}
 x_1\geq\cdots\geq x_r\geq0,
 \qquad
 1\geq y_1\geq\cdots\geq y_r\geq0.
\end{equation}
When $r=1$, the above sets of inequalities become
$1\geq d-x_1\geq0$ and $x_1\geq0$. These are linear inequalities, so $V_{r,d}$ is a convex
polytope. It is bounded because all coordinates are non-negative and their
total sum is $d$.

For $d=d_{r,N}(c)$, the same elimination reduces the
original lattice count to $2r-1$ integer coordinates; the size
condition determines the omitted coordinate uniquely as
\begin{equation*}
 b_r
 =
 n-r-\sum_{i=1}^r a_i-\sum_{i=1}^{r-1}b_i.
\end{equation*}
The right-hand side is an integer, so $y_r$ also
lies on the scaled lattice $N^{-1}\mathbb Z$. Thus every choice of the
remaining $2r-1$ scaled lattice coordinates satisfying the inequalities of
$V_{r,d_{r,N}(c)}$ determines a valid value of the omitted Frobenius
coordinate $b_r=Ny_r$. Equivalently, multiplying the independent scaled coordinates by $N$ sends
such points to integer points of $NV_{r,d_{r,N}(c)}\subset\mathbb R^{2r-1}$.
After removing the lattice points on the boundary hyperplanes corresponding to
the strict inequalities in \eqref{eq:Frobenius-coordinate-set}, the points
of $\mathcal F_r(n,N)$ are in one-to-one correspondence with the remaining
lattice points of $NV_{r,d_{r,N}(c)}\cap\mathbb Z^{2r-1}$.

Next, we define the weight
\begin{equation}
\label{eq:Prd-def}
 \mathcal P_{k,r,d}(\mathbf x,\tilde{\mathbf y})
 :=
 \Phi_{k,r}\!\left(
 \mathbf x,
 \biggl( y_1,\ldots,y_{r-1},
 d-\sum_{i=1}^r x_i-\sum_{i=1}^{r-1}y_i
 \biggr) \right)^2,
\end{equation}
where $\tilde{\mathbf y}=(y_1,\ldots,y_{r-1})$, and set
\begin{equation}
\label{eq:Jkr-def}
 J_{k,r}(d)
 :=
 \int_{V_{r,d}}
 \mathcal P_{k,r,d}(\mathbf x,\tilde{\mathbf y})
 \,d\mathbf x\,d\tilde{\mathbf y}.
\end{equation}

We verify the hypotheses of Lemma~\ref{lem:weighted-lattice-volume} with
$D=2r-1$ and with $d$ as the family parameter. As $\mathcal K$ is a compact subset of $(0,\infty)$, we may choose a
compact interval $\mathcal I\subset(0,\infty)$ whose interior contains $\mathcal K$. Let $d^+:=\max\mathcal I$. Since $1\leq r\leq R$ and
\begin{equation}
 |d_{r,N}(c)-c|
 \leq \frac{r+1}{N}
 \leq \frac{R+1}{N},
\end{equation}
we have $d_{r,N}(c)\in\mathcal I$ for all sufficiently large $N$,
uniformly for $c\in\mathcal K$ and $1\leq r\leq R$. The linear inequalities in \eqref{eq:Vrd} make $V_{r,d}$ convex. For
each $d\in \mathcal I$, choose coordinates satisfying
\begin{align*}
 1>y_1>\cdots>y_r>0,
 &\qquad
 \sum_{i=1}^r y_i<d,\\
 x_1>\cdots>x_r>0,
 &\qquad
 \sum_{i=1}^r x_i=d-\sum_{i=1}^r y_i.
\end{align*}
Every inequality in \eqref{eq:Vrd} is then strict. This produces an
interior point of $V_{r,d}$, proving that the polytope is
$(2r-1)$-dimensional. On $V_{r,d}$, one has
$0\leq y_i\leq1$ and $0\leq x_i\leq d\leq d^+$, so every polytope lies
in the common compact box
$\mathcal C_{\mathcal I}:=[0,d^+]^r\times[0,1]^{r-1}$.
As the inequalities form a fixed finite list, the number of facets is
bounded by the length of this list, and this bound is independent of $d$.

Choose a fixed bounded open neighbourhood $U$ of $\mathcal C_{\mathcal I}$. After
inserting the expression for $y_r$ from \eqref{eq:yr-eliminate},
$\mathcal P_{k,r,d}$ is polynomial jointly in the displayed $2r-1$
variables and in $d$. The polynomial and its first derivatives are
continuous on the compact set $\overline U\times \mathcal I$, so they admit a
common finite bound. The strict inequalities in \eqref{eq:Frobenius-coordinate-set} omit
only boundary lattice points satisfying $x_i=x_{i+1}$ or
$y_i=y_{i+1}$ for $1\leq i<r$, or $y_1=1$. The hyperplane-counting estimate
in the final part of the proof of
Lemma~\ref{lem:weighted-lattice-volume} shows that omitting these points
changes the sum by at most $O_{k,r,\mathcal K}(N^{2r-2})$.
Applying the lemma with $d=d_{r,N}(c)$ gives
\begin{equation}
\label{eq:weighted-volume-r}
 \sum_{(\mathbf a,\mathbf b)\in\mathcal F_r(n,N)}
 \Phi_{k,r}(\mathbf a/N,\mathbf b/N)^2
 =
 N^{2r-1}J_{k,r}(d_{r,N}(c))
 +O_{k,r,\mathcal K}(N^{2r-2}).
\end{equation} 
The parameter in \eqref{eq:weighted-volume-r} is $d_{r,N}(c)$ rather than
$c$, so we next replace it by its limiting value. Since
$n=\lfloor cN\rfloor$,
\begin{equation}
\label{eq:dN-to-c}
 |d_{r,N}(c)-c|
 =
 \left|\frac{\lfloor cN\rfloor-r}{N}-c\right|
 \leq\frac{r+1}{N}.
\end{equation}
The main term in \eqref{eq:weighted-volume-r} contains
$J_{k,r}(d_{r,N}(c))$, while the limiting coefficient involves
$J_{k,r}(c)$. By \eqref{eq:dN-to-c}, the two parameters differ by
$O_r(N^{-1})$. It is enough to prove that $J_{k,r}(d)$ is uniformly
Lipschitz in $d$: after multiplication by $N^{2r-1}$, an $O(N^{-1})$
change in $J_{k,r}$ contributes $O(N^{2r-2})$, matching the error in
\eqref{eq:weighted-volume-r}.

For the Lipschitz estimate, we continue to use the compact interval
$\mathcal I$ chosen above. In the independent
coordinates $\mathbf z=(x_1,\ldots,x_r,y_1,\ldots,y_{r-1})$, put
$S_r(\mathbf z):=\sum_{i=1}^r x_i+\sum_{i=1}^{r-1}y_i$, so that the
eliminated coordinate is $y_r=d-S_r(\mathbf z)$. For $r=1$, we have
$\mathbf z=x_1$. We refer separately to rank one only where the symbol
$y_{r-1}$ occurs; the estimates are otherwise identical.

Every $V_{r,d}$ with $d\in\mathcal I$ lies
in the fixed box
$\mathcal B_{r,\mathcal I}:=[0,d^+]^r\times[0,1]^{r-1}$, with the second
factor omitted for $r=1$. This holds because all the original coordinates are
non-negative, each $y_i$ is at most $1$, and
$\sum_{i=1}^r(x_i+y_i)=d\leq d^+$. We first estimate the change in the region.  For $r\geq2$, substituting
$y_r=d-S_r(\mathbf z)$ into $y_{r-1}\geq y_r\geq0$ gives
$S_r(\mathbf z)\leq d$ and $S_r(\mathbf z)+y_{r-1}\geq d$. All other
inequalities defining $V_{r,d}$ are independent of $d$. For $r=1$, the
corresponding conditions are $x_1\leq d$ and $x_1+1\geq d$. For $d,d'\in\mathcal I$, write
$\underline d:=\min\{d,d'\}$ and $\overline d:=\max\{d,d'\}$. A point belonging to exactly one of $V_{r,d}$ and $V_{r,d'}$ must lie
in one of the regions swept out by the two parameter-dependent
boundaries as the parameter varies between $d$ and $d'$. For
$r\geq2$, this gives
\begin{align}
\label{eq:Vrd-symmetric-difference-regions}
 V_{r,d}\mathbin{\triangle}V_{r,d'}
 \subset{}&
 \bigl\{\mathbf z\in\mathcal B_{r,\mathcal I}:
 \underline d\leq S_r(\mathbf z)\leq\overline d\bigr\}
 \nonumber\\
 &\qquad\qquad\mathbin{\cup}
 \bigl\{\mathbf z\in\mathcal B_{r,\mathcal I}:
 \underline d\leq S_r(\mathbf z)+y_{r-1}
 \leq\overline d\bigr\}.
\end{align}
For $r=1$, replace the two displayed functions by $x_1$ and $x_1+1$.

Fixing every coordinate except $x_1$, either set on the right of
\eqref{eq:Vrd-symmetric-difference-regions} restricts $x_1$ to an interval
of length at most $\overline d-\underline d=|d-d'|$.  The projection of
$\mathcal B_{r,\mathcal I}$ onto the other coordinates has bounded volume,
so Fubini's theorem gives
\begin{equation}
\label{eq:Vrd-symmetric-difference-volume}
 \operatorname{vol}_{2r-1}
 \bigl(V_{r,d}\mathbin{\triangle}V_{r,d'}\bigr)
 \ll_{r,\mathcal K}|d-d'|.
\end{equation}
For $r=1$, the sets in question are intervals of length at most $|d-d'|$, and the same estimate applies. We next estimate the change in the weight.  Formula \eqref{eq:Prd-def}
expresses $\mathcal P_{k,r,d}(\mathbf z)$ as a polynomial in
$(\mathbf z,d)$.  On the compact set
$\mathcal B_{r,\mathcal I}\times\mathcal I$, there are constants
$M_0,M_1\ll_{k,r,\mathcal K}1$ for which
\begin{equation*}
 \bigl|\mathcal P_{k,r,d}(\mathbf z)\bigr|\leq M_0,
 \qquad
 \left|\partial_d\mathcal P_{k,r,d}(\mathbf z)\right|\leq M_1.
\end{equation*}
The mean value theorem gives
$|\mathcal P_{k,r,d}(\mathbf z)-\mathcal P_{k,r,d'}(\mathbf z)|
\leq M_1|d-d'|$.
Splitting the two integrals over their common part and their disjoint
parts, we obtain
\begin{align*}
 |J_{k,r}(d)-J_{k,r}(d')|
 &\leq
 \int_{V_{r,d}\cap V_{r,d'}}
 \bigl|\mathcal P_{k,r,d}-\mathcal P_{k,r,d'}\bigr|\,d\mathbf z
 \\
 &\quad+
 \int_{V_{r,d}\setminus V_{r,d'}}
 \bigl|\mathcal P_{k,r,d}\bigr|\,d\mathbf z
 +
 \int_{V_{r,d'}\setminus V_{r,d}}
 \bigl|\mathcal P_{k,r,d'}\bigr|\,d\mathbf z
 \\
 &\leq
 M_1\operatorname{vol}_{2r-1}(\mathcal B_{r,\mathcal I})|d-d'|
 +M_0\operatorname{vol}_{2r-1}
 \bigl(V_{r,d}\mathbin{\triangle}V_{r,d'}\bigr)
 \\
 &\ll_{k,r,\mathcal K}|d-d'|.
\end{align*}
We have proved
\begin{equation}
\label{eq:Jkr-lipschitz}
 |J_{k,r}(d)-J_{k,r}(d')|
 \ll_{k,r,\mathcal K}|d-d'|,
 \qquad d,d'\in\mathcal I.
\end{equation}
Taking $d=d_{r,N}(c)$ and $d'=c$, and applying
\eqref{eq:dN-to-c}, gives
\begin{equation}
\label{eq:slice-lipschitz}
 J_{k,r}(d_{r,N}(c))
 =J_{k,r}(c)+O_{k,r,\mathcal K}(N^{-1}),
\end{equation}
uniformly for $c\in\mathcal K$.

Substituting \eqref{eq:slice-lipschitz} into
\eqref{eq:weighted-volume-r}, we obtain
\begin{equation}
\label{eq:weighted-volume-r-at-c}
 \sum_{(\mathbf a,\mathbf b)\in\mathcal F_r(n,N)}
 \Phi_{k,r}(\mathbf a/N,\mathbf b/N)^2
 =N^{2r-1}J_{k,r}(c)
 +O_{k,r,\mathcal K}(N^{2r-2}).
\end{equation}
The error from \eqref{eq:slice-lipschitz} has the same order as the
lattice-to-volume error.  Inserting
\eqref{eq:weighted-volume-r-at-c} into
\eqref{eq:Ik-after-leading-weight} gives
\begin{align*}
 I_k(n;N)
 ={}&
 \sum_{r=1}^{R}N^{2k-2r}
 \left(
 N^{2r-1}J_{k,r}(c)
 +O_{k,r,\mathcal K}(N^{2r-2})
 \right)
 +O_{k,\mathcal K}(N^{2k-2}).
\end{align*}
For each $r$, the main term has order $N^{2k-1}$ and the error has order
$N^{2k-2}$.  The number $R=\lfloor\sqrt{k}\rfloor$ depends only on $k$,
so the sum over $r$ preserves this error order.  We arrive at
\begin{equation}
\label{eq:volume-before-delta}
 I_k(n;N)
 =N^{2k-1}\sum_{r=1}^{R}J_{k,r}(c)
 +O_{k,\mathcal K}(N^{2k-2}).
\end{equation}
\subsubsection{The symmetric integral}

We now rewrite $J_{k,r}(c)$ in a symmetric form. By
\eqref{eq:Jkr-def}, $y_r$ is determined by
\eqref{eq:yr-eliminate}; equivalently, this constraint may be imposed using
the Dirac delta distribution. Integrating first with respect to $y_r$ gives
\begin{equation}
\label{eq:Jr-ordered-delta}
 J_{k,r}(c)
 =
 \int_{\substack{x_1>\cdots>x_r\geq0\\
                  1>y_1>\cdots>y_r\geq0}}
 \Phi_{k,r}(\mathbf x,\mathbf y)^2
 \delta\!\left(\sum_{i=1}^r(x_i+y_i)-c\right)
 \,d\mathbf x\,d\mathbf y.
\end{equation}
Indeed, the $y_r$-integration sets
\begin{equation*}
 y_r
 =
 c-\sum_{i=1}^r x_i-\sum_{i=1}^{r-1}y_i,
\end{equation*}
which is exactly \eqref{eq:yr-eliminate} with $d=c$. No additional factor
appears because the derivative of the delta argument with respect to $y_r$
is $1$. Replacing the strict inequalities by weak ones does not change the
integral, since the corresponding boundary hyperplanes have measure zero
within the constrained region.

It remains to remove the ordering conditions. The determinant defining
$\Phi_{k,r}$ is alternating separately in the $\mathbf x$- and
$\mathbf y$-variables: permuting the $y_j$ permutes determinant columns,
while permuting the $x_i$ permutes rows after relabelling the summation
variables $(m_1,\ldots,m_r)$. Hence, for $\sigma,\tau\in S_r$,
\begin{equation}
\label{eq:Phi-alternating}
 \Phi_{k,r}(\mathbf x_\sigma,\mathbf y_\tau)
 =
 \operatorname{sgn}(\sigma)\operatorname{sgn}(\tau)
 \Phi_{k,r}(\mathbf x,\mathbf y).
\end{equation}
It follows that $\Phi_{k,r}^2$ is invariant under separate permutations of
the $x$- and $y$-coordinates, as is the delta factor. Up to boundary sets of
measure zero, the domain
$\mathbb R_{\geq0}^r\times[0,1]^r$ is the disjoint union of the
$(r!)^2$ regions obtained by fixing one ordering of the $x_i$ and one
ordering of the $y_i$. Coordinate permutations preserve both the measure and
the integrand, so each region contributes equally. Therefore
\begin{equation}
\label{eq:Jr-unordered-delta}
 J_{k,r}(c)
 =
 \frac1{(r!)^2}
 \int_{\mathbb R_{\geq0}^r\times[0,1]^r}
 \Phi_{k,r}(\mathbf x,\mathbf y)^2
 \delta\!\left(\sum_{i=1}^r(x_i+y_i)-c\right)
 \,d\mathbf x\,d\mathbf y.
\end{equation}
Combining \eqref{eq:Jr-unordered-delta} with
\eqref{eq:volume-before-delta} proves the asserted asymptotic and the
integral formula for $\delta_k(c)$, uniformly for $c\in\mathcal K$.

\label{thm:AoT}
Let $N,k\geq1$ be integers, and let
$\mathbf p=(p_1,\ldots,p_k)$ and
$\mathbf q=(q_1,\ldots,q_k)$ belong to $\mathbb Z_{\geq1}^k$. Then
\begin{align}
\label{eq:CN-definition-theorem}
&\mathbb E_{U(N)}
\left[
 \prod_{i=1}^{k}\operatorname{Tr}(U^{p_i})
 \prod_{j=1}^{k}\overline{\operatorname{Tr}(U^{q_j})}
\right]
=
\sum_{\mathbf r,\mathbf s\in[N]_0^k}
\det_{a,b\in[N]_0}
\left[
 \mathds{1}_{\{b=a-h_a(\mathbf r,\mathbf s)\}}
\right],
\end{align}
where $\mathds{1}_{\{E\}}$ is the
indicator of the condition $E$, equal to $1$ when $E$ holds and $0$
otherwise. For $a\in[N]_0$, define
\begin{equation}
\label{eq:zero-condition}
 h_a(\mathbf r,\mathbf s)
 :=
 \sum_{i=1}^{k}p_i\mathds{1}_{\{r_i=a\}}
 -
 \sum_{j=1}^{k}q_j\mathds{1}_{\{s_j=a\}}.
\end{equation}

\label{prop:signed-lattice-count}
For $k,n,N\in\mathbb Z_{\geq 1}$, let $A_{k,n,N}^+$ and $A_{k,n,N}^-$ be the
collections of lattice points
\begin{equation}
\label{eq:signed-count-matrix}
x=
\begin{pmatrix}
 x_1^{(1)}&x_2^{(1)}&\cdots&x_k^{(1)}\\
 x_1^{(2)}&x_2^{(2)}&\cdots&x_k^{(2)}\\
 x_1^{(3)}&x_2^{(3)}&\cdots&x_k^{(3)}\\
 x_1^{(4)}&x_2^{(4)}&\cdots&x_k^{(4)}
\end{pmatrix}
\in\mathbb Z^{4k}
\end{equation}
satisfying:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=*,itemsep=0.7em]
\item
$0\leq x_i^{(1)},x_i^{(2)}\leq N-1$ and
$x_i^{(3)},x_i^{(4)}\geq1$ for $1\leq i\leq k$;

\item
$\sum_{i=1}^k x_i^{(3)}=n$ and
$\sum_{i=1}^k x_i^{(4)}=n$;

\item the map $\phi_x:[N]_0\to\mathbb Z$ defined by
\begin{equation}
\label{eq:phi-x-definition}
\phi_x(m)
=
m-
\sum_{i=1}^k x_i^{(3)}\mathds{1}_{\{x_i^{(1)}=m\}}
+
\sum_{i=1}^k x_i^{(4)}\mathds{1}_{\{x_i^{(2)}=m\}}
\end{equation}
is an even permutation of $[N]_0$ for
$A_{k,n,N}^+$, and an odd permutation of $[N]_0$ for
$A_{k,n,N}^-$.
\end{enumerate}
Then
\begin{equation}
\label{eq:exact-signed-lattice-count}
I_k(n;N)=\#A_{k,n,N}^+-\#A_{k,n,N}^-.
\end{equation}

Expanding the absolute square in \eqref{eq:variance-rmt} gives
\begin{align}
\label{eq:expanded-I_k-pq}
I_k(n;N)
=
\sum_{\substack{p_1,\ldots,p_k\geq1\\p_1+\cdots+p_k=n}}
\sum_{\substack{q_1,\ldots,q_k\geq1\\q_1+\cdots+q_k=n}}
\int_{U(N)}
\prod_{i=1}^k\operatorname{Tr}(U^{p_i})
\prod_{i=1}^k\overline{\operatorname{Tr}(U^{q_i})}\,dU.
\end{align}
In particular, $\mathbf p=(p_1,\ldots,p_k)$ and $\mathbf q=(q_1,\ldots,q_k)$ range over the ordered
compositions of $n$ into $k$ positive parts.  For fixed $\mathbf p$ and
$\mathbf q$, Theorem~\ref{thm:AoT} evaluates the integral by introducing
$\mathbf r,\mathbf s\in[N]_0^k$ and gives
\begin{equation}
\label{expanded-out-Ik-exact-count}
I_k(n;N)
=
\sum_{\substack{p_1,\ldots,p_k\geq1\\p_1+\cdots+p_k=n}}
\sum_{\substack{q_1,\ldots,q_k\geq1\\q_1+\cdots+q_k=n}}
\sum_{\mathbf r,\mathbf s\in[N]_0^k}
\det_{a,b\in[N]_0}
\left[
\mathds{1}_{\{b=a-h_a(\mathbf r,\mathbf s)\}}
\right],
\end{equation}
where
\begin{equation*}
h_a(\mathbf r,\mathbf s)
=
\sum_{i=1}^k p_i\mathds{1}_{\{r_i=a\}}
-
\sum_{i=1}^k q_i\mathds{1}_{\{s_i=a\}}.
\end{equation*}
For each choice of $\mathbf p$, $\mathbf q$, $\mathbf r$ and $\mathbf s$ in
these sums, define $x\in\mathbb Z^{4k}$ by
\begin{equation}
\label{eq:indices-exact-proposition}
x_i^{(1)}=r_i,
\qquad
x_i^{(2)}=s_i,
\qquad
x_i^{(3)}=p_i,
\qquad
x_i^{(4)}=q_i.
\end{equation}
The bounds on $\mathbf r$ and $\mathbf s$, together with the composition
conditions on $\mathbf p$ and $\mathbf q$, are precisely conditions
\textup{(i)} and \textup{(ii)}.  Conversely, the four rows of any $x$
satisfying \textup{(i)} and \textup{(ii)} recover a unique choice of
$\mathbf p$, $\mathbf q$, $\mathbf r$ and $\mathbf s$.  This construction is
therefore a bijection.

For a lattice point obtained in this way, \eqref{eq:phi-x-definition} and the
formula for $h_a(\mathbf r,\mathbf s)$ give
\begin{equation}
\label{phi-exact-lattice-count}
\phi_x(a)=a-h_a(\mathbf r,\mathbf s).
\end{equation}
Write
\begin{equation}
\label{eq:M-exact-lattice-count}
M_x=
\left[
\mathds{1}_{\{b=\phi_x(a)\}}
\right]_{a,b\in[N]_0}.
\end{equation}
The summand indexed by $\mathbf p$, $\mathbf q$, $\mathbf r$ and $\mathbf s$
is $\det M_x$. If $\phi_x(a)\notin[N]_0$ for some $a$, then row $a$ of
$M_x$ is zero. If every value of $\phi_x$ lies in $[N]_0$ but $\phi_x$ is
not injective, two rows of $M_x$ are the same standard basis vector.  In both
cases, $\det M_x=0$. Thus $\det M_x$ can be non-zero only if $\phi_x$
takes values in $[N]_0$ and is injective. As $[N]_0$ has $N$ elements,
every injective map from $[N]_0$ to itself is bijective. Therefore, 
$\det M_x$ can be non-zero only when $\phi_x$ is a permutation of $[N]_0$.
When $\phi_x$ is a permutation, the Leibniz expansion is
\begin{equation}
\label{eq:detM-exact-lattice-count}
\det M_x
=
\sum_{\tau\in S_N}
\operatorname{sgn}(\tau)
\prod_{a\in[N]_0}\mathds{1}_{\{\tau(a)=\phi_x(a)\}}.
\end{equation}
The product is non-zero only for $\tau=\phi_x$, so
$\det M_x=\operatorname{sgn}(\phi_x)$.  Under the bijection above, the points
in $A_{k,n,N}^+$ contribute $+1$, the points in $A_{k,n,N}^-$ contribute
$-1$, and all other points contribute $0$. Summing these contributions gives
\eqref{eq:exact-signed-lattice-count}.

\label{lem:exact-admissible-block-decomposition}
Let $k,n,N\in\mathbb Z_{\geq1}$. For a partition $\pi$ of $\Omega_k$, write
\begin{equation*}
[N]_0^\pi
:=
\left\{
\mathbf x=(x_B)_{B\in\pi}:x_B\in[N]_0
\right\}.
\end{equation*}
Thus $\mathbf x\in[N]_0^\pi$ assigns a position $x_B$ to each block
$B\in\pi$. For $(\pi,\sigma)\in\mathfrak B_k$, let
$\mathcal C_N(\pi,\sigma;n)$ be the set of triples
\begin{equation*}
(\mathbf p,\mathbf q,\mathbf x)
\in
\mathbb Z_{>0}^{k}\times\mathbb Z_{>0}^{k}\times[N]_0^\pi
\end{equation*}
satisfying these three conditions:
\begin{enumerate}
[label=\textup{(\roman*)},leftmargin=*,itemsep=0.7em]
\item $\displaystyle\sum_{i=1}^k p_i=n$;
\item $x_B\neq x_C$ for all distinct $B,C\in\pi$;
\item $d_B(\mathbf p,\mathbf q)=x_B-x_{\sigma(B)}$ for every $B\in\pi$.
\end{enumerate}
Summing the block equations in condition \textup{(iii)} over $B\in\pi$
and using condition \textup{(i)} gives $\sum_{j=1}^kq_j=n$. Then
\begin{equation}
\label{eq:exact-admissible-block-decomposition}
I_k(n;N)
=
\sum_{(\pi,\sigma)\in\mathfrak B_k}
\operatorname{sgn}(\sigma)\,
\#\mathcal C_N(\pi,\sigma;n).
\end{equation}

Write
$\operatorname{Cyc}(\sigma)=\{\mathcal C_1,\ldots,\mathcal C_s\}$, and
retain the sets $P_a,Q_a$ and the indices $i_a,j_a$ chosen above. To
separate the scale $t$ from the proportions assigned to the composition
entries, define the \emph{normalised balance polytope}
\begin{equation}
\label{eq:normalised-balance-polytope}
 \mathcal S_{\pi,\sigma}
 :=
 \left\{
 (\boldsymbol\alpha,\boldsymbol\beta)\in\mathbb R_{\geq0}^{2k}:
 \begin{array}{l}
 \displaystyle\sum_{i=1}^k\alpha_i=1,\\[0.4em]
 D_{\mathcal C,|\mathcal C|}
 (\boldsymbol\alpha,\boldsymbol\beta)=0
 \quad\text{for every }\mathcal C\in\operatorname{Cyc}(\sigma)
 \end{array}
 \right\}.
\end{equation}
Thus $\mathcal S_{\pi,\sigma}$ consists of non-negative composition
proportions for which $\sum_i\alpha_i=1$ and every cycle is balanced. Adding
the cycle balance equations gives
\begin{equation*}
 \sum_{i=1}^k\alpha_i-
 \sum_{j=1}^k\beta_j=0.
\end{equation*}
The first equation in \eqref{eq:normalised-balance-polytope} then gives
$\sum_j\beta_j=1$. Both coordinate sums are fixed, so
$\mathcal S_{\pi,\sigma}$ is bounded. We shall also need a point of this polytope at which every coordinate is
positive. Choose $\rho_1,\ldots,\rho_s>0$ with
$\rho_1+\cdots+\rho_s=1$. For each $a$, distribute $\rho_a$ among the
coordinates $\alpha_i$ with $i\in P_a$, using positive values, and
distribute the same amount among the coordinates $\beta_j$ with
$j\in Q_a$. The sets $P_a$ and $Q_a$ are non-empty by admissibility, so
this defines a point of $\mathcal S_{\pi,\sigma}$ with every coordinate
positive.

To describe the measure on the polytope in
\eqref{eq:normalised-balance-polytope}, first write its balance equation for
$\mathcal C_a$ explicitly. By \eqref{eq:total-cycle-displacement}, this
equation is
\begin{equation*}
D_{\mathcal C_a,|\mathcal C_a|}
(\boldsymbol\alpha,\boldsymbol\beta)
=
\sum_{i\in P_a}\alpha_i
-
\sum_{j\in Q_a}\beta_j
=
0.
\end{equation*}
Use this equation to eliminate $\beta_{j_a}$ for each $1\leq a\leq s$,
and use $\sum_i\alpha_i=1$ to eliminate $\alpha_{i_s}$. Order the equations
by the $s$ cycle balance equations and then the total equation, and order
the eliminated variables as
\begin{equation*}
\beta_{j_1},\ldots,\beta_{j_s},\alpha_{i_s}.
\end{equation*}
Each $\beta_{j_a}$ occurs in its own cycle balance equation with coefficient
$-1$ and in no other equation. The variable $\alpha_{i_s}$ occurs with
coefficient $1$ in the balance equation for $\mathcal C_s$ and in the
total equation. The resulting coefficient matrix is therefore triangular,
with diagonal entries $-1,\ldots,-1,1$. Its determinant is $(-1)^s$, whose
absolute value is $1$. Thus the equations are independent, and eliminating
them introduces no additional factor into the measure. They leave
$2k-s-1$ free coordinates, and we denote ordinary Lebesgue measure in
these coordinates by $d\mu_{\pi,\sigma}$. When $2k-s-1=0$, this measure assigns mass $1$ to the single point.

The integral in \eqref{eq:J-pi-sigma-definition} uses strictly positive
composition variables, whereas
\eqref{eq:normalised-balance-polytope} includes points with zero
coordinates. The positive point constructed above shows that no coordinate
function $\alpha_i$ or $\beta_j$ vanishes identically on the polytope. If
one of these coordinate functions is not constant, its zero set is given by
one affine equation with a non-zero coefficient in the free coordinates.
Such a set has measure zero with respect to $d\mu_{\pi,\sigma}$. If the
coordinate function is constant, it is positive and its zero set is empty.
We may therefore integrate over the closed polytope without changing the
value. The same observation will estimate the parts near the boundary that
are removed by a positive lower bound.

Set $\mathbf u=t\boldsymbol\alpha$ and
$\mathbf v=t\boldsymbol\beta$. The $2k$ differentials contribute
$t^{2k}$. The constraint on the composition total contributes $t^{-1}$,
because
\begin{equation*}
 \delta\!\left(\sum_i u_i-t\right)
 =
 t^{-1}\delta\!\left(\sum_i\alpha_i-1\right).
\end{equation*}
Each of the $s$ cycle balance constraints contributes another factor
$t^{-1}$. The linearity of the block displacements in
\eqref{eq:block-displacement-lattice} and the definition of the cycle width
in \eqref{eq:cycle-width-lattice} give
\begin{equation*}
 \omega_{\mathcal C}
 (t\boldsymbol\alpha,t\boldsymbol\beta)
 =
 t\omega_{\mathcal C}
 (\boldsymbol\alpha,\boldsymbol\beta).
\end{equation*}
After the $s+1$ constraints are taken into account, the remaining power of
$t$ is $t^{2k-s-1}$. Therefore
\begin{equation}
\label{eq:J-fixed-polytope}
 \mathcal J_{\pi,\sigma}(t;M)
 =
 t^{2k-s-1}
 \int_{\mathcal S_{\pi,\sigma}}
 \prod_{\mathcal C\in\operatorname{Cyc}(\sigma)}
 \bigl(M-t\omega_{\mathcal C}
 (\boldsymbol\alpha,\boldsymbol\beta)\bigr)_+
 \,d\mu_{\pi,\sigma}.
\end{equation}
We first compare the parameters $(t,M)$ and $(t',M')$. Set
\begin{align*}
 A_a
 :={}
 \bigl(M-t\omega_{\mathcal C_a}
 (\boldsymbol\alpha,\boldsymbol\beta)\bigr)_+, \qquad
 A'_a
 :={}
 \bigl(M'-t'\omega_{\mathcal C_a}
 (\boldsymbol\alpha,\boldsymbol\beta)\bigr)_+.
\end{align*}
The cycle widths are bounded on the fixed polytope
$\mathcal S_{\pi,\sigma}$. The parameter ranges are compact, so the
factors $A_a$ and $A'_a$ are bounded uniformly. The inequality
$|x_+-y_+|\leq|x-y|$, where $x_+:=\max\{x,0\}$, gives
\begin{equation*}
 |A_a-A'_a|
 \ll_{k,\mathcal K}
 |t-t'|+|M-M'|.
\end{equation*}
The identity
\begin{equation*}
 \prod_{a=1}^s A_a-
 \prod_{a=1}^s A'_a
 =
 \sum_{a=1}^s
 (A_a-A'_a)
 \prod_{b<a}A'_b
 \prod_{b>a}A_b
\end{equation*}
then gives
\begin{equation*}
 \left|
 \prod_{a=1}^s A_a-
 \prod_{a=1}^s A'_a
 \right|
 \ll_{k,\mathcal K}
 |t-t'|+|M-M'|.
\end{equation*}
The mean value theorem also gives
\begin{equation*}
 \left|t^{2k-s-1}-(t')^{2k-s-1}\right|
 \ll_{k,\mathcal K}|t-t'|.
\end{equation*}
Applying these estimates to \eqref{eq:J-fixed-polytope} proves the first
claim of the lemma.

We now estimate the effect of the positive lower bound. The same change of
variables gives
\begin{align*}
 \mathcal J_{\pi,\sigma}^{(\varepsilon)}(t;M)
 ={}&
 t^{2k-s-1}
 \int_{\mathcal S_{\pi,\sigma}}
 \mathds{1}_{\{\alpha_i,\beta_j\geq\varepsilon/t
 \text{ for every }i,j\}}
 \prod_{\mathcal C\in\operatorname{Cyc}(\sigma)}
 \bigl(M-t\omega_{\mathcal C}
 (\boldsymbol\alpha,\boldsymbol\beta)\bigr)_+
 \,d\mu_{\pi,\sigma}.
\end{align*}
Put $m_{\mathcal K}:=\min\mathcal K>0$. The lower bound in
$\mathcal J_{\pi,\sigma}^{(\varepsilon)}(t;M)$ restricts the integral over
$\mathcal S_{\pi,\sigma}$ to points satisfying
\begin{equation*}
\alpha_i,\beta_j\geq\frac{\varepsilon}{t}
\qquad\text{for every }i,j.
\end{equation*}
A point omitted by this restriction therefore has at least one coordinate
$\alpha_i$ or $\beta_j$ in the interval
\begin{equation*}
0\leq\alpha_i\leq\frac{\varepsilon}{t}
\qquad\text{or}\qquad
0\leq\beta_j\leq\frac{\varepsilon}{t}.
\end{equation*}
As $t\geq m_{\mathcal K}$, the selected coordinate is at most
$\varepsilon/m_{\mathcal K}$.

By a coordinate function, we mean one of the maps
\begin{equation*}
(\boldsymbol\alpha,\boldsymbol\beta)\longmapsto\alpha_i,
\qquad
(\boldsymbol\alpha,\boldsymbol\beta)\longmapsto\beta_j.
\end{equation*}
Denote any one of these functions by $L$. Write
$d:=2k-s-1$ and let
$\boldsymbol\xi=(\xi_1,\ldots,\xi_d)$ be the free coordinates used to
define $d\mu_{\pi,\sigma}$. Eliminating the remaining coordinates expresses
$L$ as an affine function
\begin{equation*}
L(\boldsymbol\xi)
=
b+\sum_{r=1}^{d}c_r\xi_r.
\end{equation*}
The positive point constructed above shows that $L$ is not identically
zero. If $c_1=\cdots=c_d=0$, then $L=b>0$, so
$0\leq L\leq\varepsilon/m_{\mathcal K}$ has no solutions for sufficiently
small $\varepsilon$.

Now suppose that $L$ is not constant. Choose $r$ with $c_r\neq0$, and set
\begin{equation*}
z:=\xi_r,
\qquad
\mathbf w:=
(\xi_1,\ldots,\xi_{r-1},\xi_{r+1},\ldots,\xi_d),
\qquad
a:=c_r.
\end{equation*}
Then
\begin{equation*}
L(z,\mathbf w)
=
az+L_0(\mathbf w),
\qquad
L_0(\mathbf w)
:=
b+\sum_{h\neq r}c_h\xi_h.
\end{equation*}
For each fixed $\mathbf w$, the inequalities
\begin{equation*}
0\leq az+L_0(\mathbf w)
\leq\frac{\varepsilon}{m_{\mathcal K}}
\end{equation*}
restrict $z$ to an interval of length at most
\begin{equation*}
\frac{\varepsilon}{m_{\mathcal K}|a|}.
\end{equation*}
The set of possible values of $\mathbf w$ has bounded volume. Fubini's
theorem therefore gives
\begin{equation*}
 \int_{\mathcal S_{\pi,\sigma}}
 \mathds{1}_{\{0\leq L\leq\varepsilon/m_{\mathcal K}\}}
 \,d\mu_{\pi,\sigma}
 =O_{k,\mathcal K}(\varepsilon).
\end{equation*}
There are $2k$ coordinate functions, so the removed part has volume
$O_{k,\mathcal K}(\varepsilon)$. The factor outside the integral and the
integrand in \eqref{eq:J-fixed-polytope} are bounded uniformly for the
stated parameter ranges. The removed part therefore contributes
$O_{k,\mathcal K}(\varepsilon)$, which proves the second claim.

\label{prop:p-explicit}
Let $k\geq 1$ and $1 \leq r \leq k$ be integers. If $(\alpha,\beta)\in\mathcal A_{k,r}$, then
\begin{equation}\label{eq:p-explicit}
 p_{\alpha,\beta}^{(k,r)}
 =
 \frac{(-1)^{|\beta|}(k!)^2}{(\alpha!\beta!)^2}
 \sum_{\substack{0\leq u\leq\alpha,\;0\leq v\leq\beta\\
                 |u|+|v|=k-r}}
 \binom{\alpha}{u}^{\!2}
 \binom{\beta}{v}^{\!2}
 D_r(u,v)D_r(\alpha-u,\beta-v),
\end{equation}
with $\mathcal A_{k,r}$ as defined in \eqref{eq:p-support-set} and $D_r(u,v)$ in \eqref{eq:Dr-definition}.

We begin with the binomial form of the Legendre polynomial,
\begin{equation}\label{eq:Legendre-binomial-form}
 P_n(z)
 =
 2^{-n}\sum_{a=0}^n
 \binom{n}{a}^{\!2}
 (z-1)^{n-a}(z+1)^a.
\end{equation}
Substituting $z=(x-y)/(x+y)$ into the above and multiplying by $(x+y)^n$ gives the
polynomial identity
\begin{equation}\label{eq:Legendre-homogeneous-expansion}
 (x+y)^nP_n\!\left(\frac{x-y}{x+y}\right)
 =
 \sum_{\substack{a,b\geq0\\a+b=n}}
 (-1)^b\binom{n}{a}^{\!2}x^ay^b.
\end{equation}
Here the latter is not a double sum over independent indices: the constraint $a+b=n$ uniquely determines $b$, so this remains a single sum with $n+1$ terms.
Using \eqref{eq:Theta-legendre-def}, we obtain
\begin{equation}\label{eq:Psi-monomial-expansion}
 \Theta_m(x,y)
 =
 \sum_{\substack{a,b\geq0\\a+b=m-1}}
 \frac{(-1)^b}{(a!b!)^2(a+b+1)}x^ay^b.
\end{equation}
In particular, $\Theta_m$ is a homogeneous polynomial of degree $m-1$, i.e. every monomial $x^ay^b$ appearing in it has total degree $m-1$. For every choice of positive integers $m_1,\ldots,m_r$ with $m_1+\cdots+m_r=k$, each term in
$\det[\Theta_{m_i}(x_i,y_j)]$ selects exactly one entry from each row.
The entry selected from row $i$ has total degree $m_i-1$, so every term in the determinant has total degree
\begin{equation*}
\sum_{i=1}^r(m_i-1)=k-r.
\end{equation*}
Therefore $\Phi_{k,r}$ is homogeneous of degree $k-r$, and $\Phi_{k,r}^2$ is homogeneous of degree $2(k-r)$.

We now expand the determinant in \eqref{eq:Phi-def} using Leibniz's formula and insert \eqref{eq:Psi-monomial-expansion}. For a fixed permutation $\sigma\in S_r$, the associated product in the expansion is
\begin{equation*}
 \prod_{i=1}^r \Theta_{m_i}(x_i,y_{\sigma(i)}).
\end{equation*}
We reindex the exponents by writing $u_i=a_i$ and $b_i=v_{\sigma(i)}$. Thus, for fixed $u,v\in\mathbb Z_{\geq0}^r$, the $i$th factor $\Theta_{m_i}(x_i,y_{\sigma(i)})$ must contribute the monomial $x_i^{u_i}y_{\sigma(i)}^{v_{\sigma(i)}}$. By \eqref{eq:Psi-monomial-expansion}, its coefficient is
\begin{equation*}
 \frac{(-1)^{v_{\sigma(i)}}}
 {(u_i!v_{\sigma(i)}!)^2
 \bigl(u_i+v_{\sigma(i)}+1\bigr)},
\end{equation*}
and the same expansion requires the exponents in this factor to satisfy $u_i+v_{\sigma(i)}=m_i-1$, and hence $m_i=u_i+v_{\sigma(i)}+1$. Summing over $i$ gives
\begin{equation*}
 \sum_{i=1}^r m_i
 =
 \sum_{i=1}^r u_i
 +
 \sum_{i=1}^r v_{\sigma(i)}
 +
 r
 =
 |u|+|v|+r,
\end{equation*}
and multiplying the row coefficients gives
\begin{align*}
 \prod_{i=1}^r
 \frac{(-1)^{v_{\sigma(i)}}}
 {(u_i!v_{\sigma(i)}!)^2
 \bigl(u_i+v_{\sigma(i)}+1\bigr)}
 &=
 \frac{(-1)^{|v|}}{(u!v!)^2}
 \prod_{i=1}^r
 \frac{1}{u_i+v_{\sigma(i)}+1},
\end{align*}
because $\sum_i v_{\sigma(i)}=|v|$ and
$\prod_i v_{\sigma(i)}!=v!$. Summing these contributions over
$\sigma\in S_r$, with the $\operatorname{sgn}(\sigma)$ from
Leibniz's formula, yields
\begin{align}
 \Phi_{k,r}(\mathbf x,\mathbf y)
 &={}
 k!\!\sum_{\substack{u,v\in\mathbb Z_{\geq0}^r\\
                      |u|+|v|=k-r}}
 \frac{(-1)^{|v|}}{(u!v!)^2}
 \left(
  \sum_{\sigma\in S_r}
  \operatorname{sgn}(\sigma)
  \prod_{i=1}^r\frac{1}{u_i+v_{\sigma(i)}+1}
 \right)
 \mathbf x^u\mathbf y^v
 \notag\\
 &={}
 k!\!\sum_{\substack{u,v\in\mathbb Z_{\geq0}^r\\
                      |u|+|v|=k-r}}
 \frac{(-1)^{|v|}D_r(u,v)}{(u!v!)^2}
 \mathbf x^u\mathbf y^v.
 \label{eq:Phi-explicit-monomial}
\end{align}
The inner sum in the first line is exactly the determinant
in \eqref{eq:Dr-definition}.

It remains to square \eqref{eq:Phi-explicit-monomial}.  Suppose that
$(\alpha,\beta)\in\mathcal A_{k,r}$.  If one factor contributes the
exponents $(u,v)$, the other must contribute
$(\alpha-u,\beta-v)$.  The first factor has total degree $k-r$ exactly
when $|u|+|v|=k-r$; because
$|\alpha|+|\beta|=2(k-r)$, the complementary pair then has the same total
degree.  Hence
\begin{align*}
 p_{\alpha,\beta}^{(k,r)}
 ={}&(k!)^2
 \sum_{\substack{0\leq u\leq\alpha,\;0\leq v\leq\beta\\
                  |u|+|v|=k-r}}
 \frac{(-1)^{|v|+|\beta-v|}
       D_r(u,v)D_r(\alpha-u,\beta-v)}
 {(u!v!)^2((\alpha-u)!(\beta-v)!)^2}.
\end{align*}
The sign becomes $(-1)^{|\beta|}$, and the componentwise factorial identities
give
\begin{equation*}
 \frac{1}{(u!(\alpha-u)!)^2}
 =
 \frac{1}{(\alpha!)^2}\binom{\alpha}{u}^{\!2},
 \qquad
 \frac{1}{(v!(\beta-v)!)^2}
 =
 \frac{1}{(\beta!)^2}\binom{\beta}{v}^{\!2}.
\end{equation*}
Substitution gives \eqref{eq:p-explicit}.  If
$(\alpha,\beta)\notin\mathcal A_{k,r}$, the coefficient is zero by the
homogeneity proved above.

We begin by substituting the expansion \eqref{eq:p-definition2} into \eqref{eq:delta-def}. As this expansion is finite, we may integrate term by term, so the evaluation of $\delta_k(c)$ reduces to computing the contribution from each term $\mathbf x^\alpha\mathbf y^\beta$. For $(\alpha,\beta)\in\mathcal A_{k,r}$, set
\begin{equation}\label{eq:monomial-delta-integral}
 \mathcal I_{\alpha,\beta}^{(r)}(c)
 :=
 \int_{\mathbb R_{\geq0}^r\times[0,1]^r}
 \mathbf x^\alpha\mathbf y^\beta
 \delta \hspace{0.02in} \biggl(\sum_{i=1}^r(x_i+y_i)-c\biggr)
 \,d\mathbf x\,d\mathbf y.
\end{equation}
Using Theorem~\ref{thm:leading-volume}, we obtain
\begin{equation}\label{eq:delta-monomial-integral}
 \delta_k(c)
 =
 \sum_{r=1}^{\lfloor\sqrt{k}\rfloor}\frac{1}{(r!)^2}
 \sum_{(\alpha,\beta)\in\mathcal A_{k,r}}
 p_{\alpha,\beta}^{(k,r)}
 \mathcal I_{\alpha,\beta}^{(r)}(c).
\end{equation}
We use the convention $t_+^0:=\mathds{1}_{\{t>0\}}$.
For $t\neq0$, the Dirichlet simplex identity gives
\begin{equation}\label{eq:Dirichlet-simplex-integral}
 \int_{\mathbb R_{\geq0}^r}
 \mathbf x^\alpha \,
 \delta \hspace{0.01in} \biggl(\sum_{i=1}^r x_i-t\biggr)d\mathbf x
 =
 \frac{\alpha!}{(|\alpha|+r-1)!}
 t_+^{|\alpha|+r-1}.
\end{equation}
The value at $t=0$ does not affect the subsequent integrals. With $ d=d_{\alpha,r}=|\alpha|+r-1$ and $t=c-\sum_i y_i$, the above gives
\begin{equation}\label{eq:monomial-cube-reduction}
 \mathcal I_{\alpha,\beta}^{(r)}(c)
 =
 \frac{\alpha!}{d!}\,I_{\beta,d}(c),
 \qquad
 I_{\beta,d}(c)
 :=
 \int_{[0,1]^r}
 \mathbf y^\beta
 \biggl(c-\sum_{i=1}^r y_i\biggr)_+^d d\mathbf y.
\end{equation}
We first evaluate $I_{\beta,d}(c)$ for arbitrary $c>0$. The integral is
over the cube $[0,1]^r$, so in addition to $y_i\geq0$ we must impose the
upper bounds $y_i\leq1$. We do this by an inclusion--exclusion mechanism. 
Let $[r] := \{1,2,\ldots, r\}$ and
\begin{equation*}
 f(\mathbf y)
 :=
 \mathbf y^\beta
 \biggl(c-\sum_{i=1}^r y_i\biggr)_+^d.
\end{equation*}
On the region $\mathbf y\in\mathbb R_{\geq0}^r$, the condition
$0\leq y_i<1$ has indicator $1-\mathds{1}_{\{y_i\geq1\}}$. Hence the indicator of the cube $[0,1)^r$ is
\begin{equation*}
 \prod_{i=1}^r\left(1-\mathds{1}_{\{y_i\geq1\}}\right).
\end{equation*}
Expanding this product amounts to choosing, for each subset
$S\subseteq[r]$, the factor $-\mathds{1}_{\{y_i\geq1\}}$ for every
$i\in S$ and the factor $1$ for every $i\notin S$. Therefore
\begin{equation*}
 \prod_{i=1}^r\left(1-\mathds{1}_{\{y_i\geq1\}}\right)
 =
 \sum_{S\subseteq[r]}(-1)^{|S|}
 \prod_{i\in S}\mathds{1}_{\{y_i\geq1\}}.
\end{equation*}
Multiplying by $f(\mathbf y)$ and integrating over
$\mathbb R_{\geq0}^r$ gives
\begin{align}
 I_{\beta,d}(c)
 ={}&
 \sum_{S\subseteq[r]}(-1)^{|S|}
 \int_{\substack{\mathbf y\in\mathbb R_{\geq0}^r\\
                  y_i\geq1\ (i\in S)}}
 \mathbf y^\beta
 \biggl(c-\sum_{i=1}^r y_i\biggr)_+^d
 \,d\mathbf y.
 \label{eq:cube-inclusion-exclusion}
\end{align}
Replacing
$[0,1)^r$ by $[0,1]^r$ does not change the integral, because their
difference lies on the boundary $y_i=1$, which has measure zero.

We now evaluate the integral corresponding to each subset $S\subseteq[r]$. For $i\in S$, the condition $y_i\geq1$ gives a lower bound of $1$, while the simplex formula is most naturally applied when all variables start at $0$. We therefore set $y_i=1+z_i$ for $i\in S$ and $y_i=z_i$ for $i\notin S$. This change of variables maps the region of integration onto
$\mathbb R_{\geq0}^r$ and has Jacobian $1$. It also gives
\begin{equation*}
 c-\sum_{i=1}^r y_i
 =
 c-|S|-\sum_{i=1}^r z_i, \qquad \text{and} \qquad  \mathbf y^\beta
 =
 \prod_{i\in S}(1+z_i)^{\beta_i}
 \prod_{i\notin S}z_i^{\beta_i}.
\end{equation*}
To reduce the shifted factors to ordinary powers of the $z_i$, we expand
\begin{equation*}
 (1+z_i)^{\beta_i}
 =
 \sum_{q_i=0}^{\beta_i}
 \binom{\beta_i}{q_i}z_i^{\beta_i-q_i},
 \qquad i\in S.
\end{equation*}
For each fixed choice of $q_i$, define
\begin{equation*}
 \gamma_i
 =
 \begin{cases}
  \beta_i-q_i, & i\in S,\\
  \beta_i, & i\notin S.
 \end{cases}
\end{equation*}
Then $|\gamma|=|\beta|-\sum_{i\in S}q_i$ and the corresponding integral has the form
\begin{equation*}
 \int_{\mathbb R_{\geq0}^r}
 \mathbf z^\gamma
 \Bigl(c-|S|-\sum_{i=1}^r z_i\Bigr)_+^d
 \,d\mathbf z.
\end{equation*}
We evaluate these integrals using the following consequence of the simplex
integral formula: for $\gamma\in\mathbb Z_{\geq0}^r$,
$d\in\mathbb Z_{\geq0}$, and $\rho\in\mathbb R$,
\begin{equation}
\label{eq:augmented-Dirichlet-integral}
 \int_{\mathbb R_{\geq0}^r}
 \mathbf z^\gamma
 \left(\rho-\sum_{i=1}^r z_i\right)_+^d
 \,d\mathbf z
 =
 \frac{\gamma!\,d!}{(d+|\gamma|+r)!}
 \rho_+^{d+|\gamma|+r}.
\end{equation}
To verify this identity, introduce one additional variable
$w=\rho-\sum_{i=1}^r z_i$. The integral may then be written as
\begin{equation*}
 \int_{\mathbb R_{\geq0}^{r+1}}
 \mathbf z^\gamma w^d
 \delta\!\left(\sum_{i=1}^r z_i+w-\rho\right)
 \,d\mathbf z\,dw,
\end{equation*}
and \eqref{eq:augmented-Dirichlet-integral} follows from
\eqref{eq:Dirichlet-simplex-integral} in dimension $r+1$.

Applying \eqref{eq:augmented-Dirichlet-integral} with $\rho=c-|S|$ to each
term in the binomial expansion gives
\begin{align*}
 I_{\beta,d}(c)
 ={}&
 \sum_{S\subseteq[r]}(-1)^{|S|}
 \sum_{\substack{0\leq q_i\leq\beta_i\\ i\in S}}
 \left(\prod_{i\in S}\binom{\beta_i}{q_i}\right)
 \frac{\gamma!\,d!}
 {\left(d+|\gamma|+r\right)!}
 (c-|S|)_+^{d+|\gamma|+r}.
\end{align*}
The factorials simplify using
\begin{equation*}
 \left(\prod_{i\in S}\binom{\beta_i}{q_i}\right)\gamma!
 =
 \frac{\beta!}{\displaystyle\prod_{i\in S}q_i!}.
\end{equation*}
Setting $M:=d+|\beta|+r$ and using $d+|\gamma|+r
 = M-\sum_{i\in S}q_i$, we obtain
\begin{equation}
\label{eq:cube-moment-spline}
 I_{\beta,d}(c)
 =
 \beta!d!
 \sum_{S\subseteq[r]}(-1)^{|S|}
 \sum_{\substack{0\leq q_i\leq\beta_i\\ i\in S}}
 \frac{(c-|S|)_+^{M-\sum_{i\in S}q_i}}
 {\left(M-\sum_{i\in S}q_i\right)!
 \displaystyle\prod_{i\in S}q_i!}.
\end{equation}
For $(\alpha,\beta)\in\mathcal A_{k,r}$, the support relation
$|\alpha|+|\beta|=2(k-r)$ gives
\begin{equation}
\label{eq:M-equals-2k-minus-1}
 M
 =
 d_{\alpha,r}+|\beta|+r
 =
 |\alpha|+|\beta|+2r-1
 =
 2k-1.
\end{equation}
Substituting \eqref{eq:cube-moment-spline} into
\eqref{eq:monomial-cube-reduction}, and then using
\eqref{eq:delta-monomial-integral}, gives the finite-spline expansion stated
in the theorem.

We now suppose that $c\geq\lfloor\sqrt{k}\rfloor$. Every rank in
\eqref{eq:delta-monomial-integral} satisfies $r\leq\lfloor\sqrt{k}\rfloor$, and therefore $c\geq r$. Moreover, for $\mathbf y\in[0,1]^r$, we have $\sum_{i=1}^r y_i\leq r\leq c$. Hence $c-\sum_i y_i\geq0$ throughout the cube, so the positive-part truncation in
\eqref{eq:monomial-cube-reduction} may be omitted (the possible equality at
the boundary does not affect the integral). As $d$ is a non-negative
integer, the multinomial theorem gives the finite expansion
\begin{equation}\label{eq:multinomial-FA-expansion}
 \biggl(c-\sum_{i=1}^r y_i\biggr)^d
 =
 c^d
 \sum_{m\in\mathbb Z_{\geq0}^r, \, |m|\leq d}
 \frac{(-d)_{|m|}}{m!}
 \prod_{i=1}^r\left(\frac{y_i}{c}\right)^{m_i}.
\end{equation}
The sum is finite, so it may be integrated term by term.  For every $i$,
\begin{equation}\label{eq:Pochhammer-ratio}
 \int_0^1y_i^{\beta_i+m_i}\,dy_i
 =
 \frac{1}{\beta_i+1}
 \frac{(\beta_i+1)_{m_i}}{(\beta_i+2)_{m_i}}.
\end{equation}
Combining these last two results, and comparing the resulting finite
series with the definition in \eqref{eq:FA-definition}, we obtain
\begin{equation}\label{eq:cube-moment-FA}
 I_{\beta,d}(c)
 =
 \frac{c^d}{\displaystyle\prod_{i=1}^r(\beta_i+1)}
 F_A^{(r)}
 \left(
  -d;
  \beta+\mathbf1_r;
  \beta+2\mathbf1_r;
  c^{-1}\mathbf1_r
 \right).
\end{equation}
Substituting \eqref{eq:cube-moment-FA} into
\eqref{eq:monomial-cube-reduction}, and then into
\eqref{eq:delta-monomial-integral}, proves
\eqref{eq:delta-Lauricella}. Since $(-d)_{|m|}=0$ for $|m|>d$, every
Lauricella series here terminates. Thus the argument requires neither a
convergence condition nor analytic continuation, and it remains valid at
$c=\lfloor\sqrt{k}\rfloor$.

For completeness, the same formulas justify the two structural observations
following the theorem. Each term in \eqref{eq:delta-Lauricella} is a
polynomial in $c$ of degree at most $d_{\alpha,r}$, and
\begin{equation*}
 d_{\alpha,r}
 =|\alpha|+r-1
 \leq2(k-r)+r-1
 \leq2k-2.
\end{equation*}
At a candidate breakpoint $j$, only the terms with $|S|=j$ in
\eqref{eq:cube-moment-spline} change from zero to non-zero. Their truncated
powers have exponent
\begin{equation*}
 2k-1-\sum_{i\in S}q_i
 \geq2k-1-|\beta|
 \geq2r-1
 \geq2j-1.
\end{equation*}
Consequently each such term is $C^{2j-2}$ at $c=j$, and so is
$\delta_k(c)$.

\label{rem:FB-spline}
The Lauricella family $F_B$ is distinct from the family $F_A$ used in \eqref{eq:delta-Lauricella}. For $s\geq1$,
$\mathbf a,\mathbf b,\mathbf z\in\mathbb C^s$, 
$\gamma\notin\{0,-1,-2,\ldots\}$, and $|z_i|<1$ for every $i$, define
\begin{equation*}
 F_B^{(s)}(\mathbf a;\mathbf b;\gamma;\mathbf z)
 =
 \sum_{m_1,\ldots,m_s\geq0}
 \frac{1}{(\gamma)_{|m|}}
 \prod_{i=1}^s
 \frac{(a_i)_{m_i}(b_i)_{m_i}}{m_i!}z_i^{m_i},
 \qquad |m|=m_1+\cdots+m_s.
\end{equation*}
For $S\subseteq[r]$, put $B_S=\sum_{i\in S}\beta_i,$
and $ t_S=(c-|S|)_+$. Write $\beta_S=(\beta_i)_{i\in S}$ and $\mathbf1_S=(1)_{i\in S}$.
Then the innermost sum in the finite-spline formula of Theorem~\ref{thm:lauricella} may be replaced exactly by
\begin{align*}
 &\sum_{\substack{0\leq q_i\leq\beta_i\\ i\in S}}
 \hspace{-0.02in} \frac{t_S^{\,2k-1-\sum_{i\in S}q_i}}
 {\left(2k-1-\sum_{i\in S}q_i\right)!
  \displaystyle\prod_{i\in S}q_i!}
 \hspace{-0.02in} = \hspace{-0.02in}
 \frac{t_S^{\,2k-1-B_S}}
 {(2k-1-B_S)!\displaystyle\prod_{i\in S}\beta_i!}
 F_B^{(|S|)}
 \left(
 -\beta_S;\mathbf1_S;
 2k-B_S;
 -t_S\mathbf1_S
 \right).
\end{align*}
Since every component of $-\beta_S$ is a non-positive integer, this $F_B^{(|S|)}$ series terminates and hence introduces no convergence restriction.
For $S=\varnothing$, both sides are interpreted as $c^{2k-1}/(2k-1)!$, while on the final polynomial range the resulting alternating sum of terminating $F_B$ polynomials is equal to the $F_A$ expression in \eqref{eq:delta-Lauricella}.

\label{thm:two-centre-P-input}
Let $k\in\mathbb N$. For $\alpha>0$,
\begin{equation}\label{eq:two-centre-M-P}
 M_k(\alpha)=\frac1{k!^2}\sum_{0\leq r<\alpha}\binom{k}{r}^{\!2}P_{r,k}(\alpha),
\end{equation}
where, for $0\leq r\leq k$,
\begin{align}
 P_{r,k}(\alpha)
 ={}&\frac1{(2\pi i)^{2k}}
 \sum_{a=0}^k\frac{(-1)^{k-a}}{(k+a)!}\binom{k}{a}
 \int_{\mathbf c(r)}\int_{\hat{\mathbf c}(r)}
 \bigl(T(\mathbf x)-\alpha\bigr)^{k+a} \, \Delta(\mathbf x)^2\Delta(\mathbf y)^2
 \prod_{j,\ell=1}^k(x_j-y_\ell-1)
 \notag\\[-1mm]
 &\times
 \left(
   \sum_{j=1}^k\frac1{x_j}
   +\sum_{\ell=1}^k\frac1{y_\ell+1}
 \right)^{\!a}
 \left(
   \sum_{j=1}^k\frac1{x_j-1}
   +\sum_{\ell=1}^k\frac1{y_\ell}
 \right)^{\!k}
 \prod_{j=1}^k x_j^{-k}
 \prod_{\ell=1}^k y_\ell^{-k}
 \,d\mathbf x\,d\mathbf y,
 \label{eq:two-centre-P-original}
\end{align}
where $\Delta(\mathbf{x})=\prod_{i < j}(x_j - x_i)$ and we use
$d\mathbf x=\prod_{j=1}^k dx_j$, $d\mathbf y=\prod_{\ell=1}^k dy_\ell$.
For $r>k$, set $P_{r,k}(\alpha)=0$.  Moreover, $P_{r,k}(\alpha)$ has a zero of
order at least $2r^2$ at $\alpha=r$.

\label{prop:derivative-relationship}
Let $k\geq1$ be a fixed integer. For $\alpha>0$,
\begin{equation}
\label{eq:Mk-derivative}
 M_k'(\alpha)=\delta_k(\alpha).
\end{equation}

Equations~\eqref{eq:Jkr-lipschitz} and
\eqref{eq:Jr-unordered-delta} show that $\delta_k$ is locally Lipschitz,
and hence continuous, on $(0,\infty)$. Haar invariance under
$U\mapsto e^{i\varphi}U$ gives
\begin{equation}
\label{eq:Itilde-riemann-sum}
 \frac{\tilde I_k(\lfloor \alpha N\rfloor;N)}{N^{2k}}
 =
 \frac1N\sum_{m=k}^{\lfloor \alpha N\rfloor}
 \frac{I_k(m;N)}{N^{2k-1}}.
\end{equation}
Fix $0<\eta<\min(1,\alpha)$ and split the sum at
$m=\lfloor\eta N\rfloor$. On the range $ \lfloor\eta N\rfloor<m\leq\lfloor \alpha N\rfloor$, the ratio $m/N$ lies in the compact interval $[\eta,\alpha]$.
Theorem~\ref{thm:leading-volume} therefore applies uniformly to these
summands. After the normalisation in \eqref{eq:Itilde-riemann-sum}, the
accumulated error is $O(N^{-1})$, while the main terms form a Riemann sum
converging to $\int_\eta^\alpha \delta_k(c) \, dc $.

The remaining range
\begin{equation*}
 k\leq m\leq\lfloor\eta N\rfloor
\end{equation*}
is not uniformly bounded away from $m/N=0$ and hence is not covered by
the compact-uniform estimate in Theorem~\ref{thm:leading-volume}.
Since $\eta<1$, however, this range satisfies $m\leq N$ for all
sufficiently large $N$ and therefore lies in the stable range. By
\eqref{eq:Ik-stable-range} and \eqref{eq:delta-stable-range},
\begin{equation*}
 \frac1N
 \sum_{m=k}^{\lfloor\eta N\rfloor}
 \frac{I_k(m;N)}{N^{2k-1}}
 \longrightarrow
 \int_0^\eta\delta_k(c)\,dc.
\end{equation*}
Combining the two ranges and using the definition of $M_k(\alpha)$ gives
\begin{equation}
\label{eq:Mk-integral}
 M_k(\alpha)
 =
 \int_0^\eta\delta_k(c)\,dc
 +
 \int_\eta^\alpha \delta_k(c)\,dc
 =
 \int_0^\alpha \delta_k(c)\,dc.
\end{equation}
Equation~\eqref{eq:Mk-derivative} now follows from the continuity of
$\delta_k$ and the fundamental theorem of calculus.

Fix an integer $k\geq1$, and let $\alpha>0$ be real. We differentiate the 
$2k$-contour formula in Theorem~\ref{thm:two-centre-P-input}, and then organise the result in terms of a two-weight multiple Hankel
determinant. The key observation is that the $r$-th contour sector, i.e. the $r$-th term in \eqref{eq:two-centre-M-P},
contributes only for $\alpha>r$. The only point requiring care in differentiating
\eqref{eq:two-centre-M-P} is that the summation range changes when
$\alpha$ crosses an integer. Since $P_{r,k}=0$ for $r>k$, we may replace
this varying range by the fixed sum
\begin{equation}\label{eq:two-centre-M-fixed-sum}
 M_k(\alpha)
 =
 \frac1{k!^2}
 \sum_{r=0}^k
 \binom{k}{r}^{\!2}
 \mathds{1}_{\{\alpha>r\}}P_{r,k}(\alpha),
 \qquad \alpha>0,
\end{equation}
where the indicator retains the original condition $r<\alpha$. For
$r\geq1$, Theorem~\ref{thm:two-centre-P-input} gives
$P_{r,k}(r)=P'_{r,k}(r)=0$, so the function
$\alpha\mapsto\mathds{1}_{\{\alpha>r\}}P_{r,k}(\alpha)$ is continuously
differentiable at $\alpha=r$. For $r=0$, the indicator is identically one
on $\alpha>0$. Evaluating at $\alpha=c$ and using $M_k'(c)=\delta_k(c)$, we obtain
\begin{equation}\label{eq:two-centre-delta-fixed-sum}
 \delta_k(c)
 =
 \frac1{k!^2}
 \sum_{r=0}^k
 \binom{k}{r}^{\!2}
 \mathds{1}_{\{c>r\}}P'_{r,k}(c),
 \qquad c>0.
\end{equation}
We may simplify $P_{r,k}(c)$ by using $(-1)^{k-a}\bigl(T(\mathbf x)-c\bigr)^{k+a}
 =
 \bigl(c -T(\mathbf x)\bigr)^{k+a}$. Thus, on the range $c>r$, differentiating the ordinary polynomial $P_{r,k}(c)$ gives the same contour integral as
\eqref{eq:two-centre-P-original}, with
\begin{equation*}
 \frac{\bigl(c -T(\mathbf x)\bigr)^{k+a-1}}
      {(k+a-1)!}
\end{equation*}
in place of the original power.

It remains to encode the factor $\mathds{1}_{\{c>r\}}$.  Because the variables $x_j$ lie on complex contours, the notation
$(c-T(\mathbf x))_+^m$ will not mean the pointwise positive part of a
complex number. Instead, for the rational contour factors occurring here, we use it as shorthand for the residue-first
inverse Laplace expression
\begin{align}
\int_{\mathbf c(r)}\int_{\hat{\mathbf c}(r)}
 \hspace{-0.05in} \frac{(c-T(\mathbf x))_+^m}{m!}
 F(\mathbf x,\mathbf y)\,d\mathbf x\,d\mathbf y
:=
 \mathcal L^{-1}_{s\to c}
 \left[
  \frac1{s^{m+1}}
  \int_{\mathbf c(r)}\int_{\hat{\mathbf c}(r)}
  e^{-sT(\mathbf x)}
  F(\mathbf x,\mathbf y)\,d\mathbf x\,d\mathbf y
 \right] \hspace{-0.05in}.
\label{eq:two-centre-residue-first}
\end{align}
The contour residues inside the square brackets are evaluated before the
inverse Laplace transform is taken. To see how this expression encodes the threshold $c=r$, write in the
$r$-th contour sector
\begin{equation*}
 x_j=\varepsilon_j+\xi_j,
 \qquad
 \varepsilon_j=
 \begin{cases}
  1,&j\leq r,\\
  0,&j>r.
 \end{cases}
\end{equation*}
Then
\begin{equation*}
 T(\mathbf x)=r+\sum_{j=1}^k\xi_j,
 \qquad
 e^{-sT(\mathbf x)}
 =
 e^{-rs}
 \exp\!\biggl(-s\sum_{j=1}^k\xi_j\biggr).
\end{equation*}
The contour poles have finite order, so evaluating the residues uses only
finitely many terms in the Taylor series of the final exponential.  The
result is therefore \(e^{-rs}\) multiplied by a finite Laurent polynomial
in \(s\).  Its negative powers are inverted using
\begin{equation}\label{eq:two-centre-shifted-Laplace}
 \mathcal L^{-1}_{s\to c}
 \left[e^{-rs}s^{-q}\right]
 =
 \frac{(c-r)_+^{q-1}}{(q-1)!},
 \qquad q\geq1.
\end{equation}
Every such term is zero for $c<r$ and becomes an ordinary polynomial in
$c-r$ for $c>r$.  Consequently, away from $c=r$, the residue-first
expression in \eqref{eq:two-centre-residue-first} is precisely the ordinary
contour polynomial multiplied by $\mathds{1}_{\{c>r\}}$. At $c=r$, the
complete $r$-th sector is assigned its continuous value; this is
well-defined because $P_{r,k}(r)=P'_{r,k}(r)=0$.

We now shift the $y$-variables by setting $ w_\ell=y_\ell+1$ for $1\leq\ell\leq k$. In the sector indexed by $r$, the contours become
\begin{equation}\label{eq:two-centre-contour-system}
 x_j\in
 \begin{cases}
  C_1,&j\leq r,\\
  C_0,&j>r,
 \end{cases}
 \qquad
 w_\ell\in
 \begin{cases}
  C_0,&\ell\leq r,\\
  C_1,&\ell>r.
 \end{cases}
\end{equation}
Denote these iterated contour systems by $\mathcal C_x(r)$ and $\mathcal C_w(r)$, and write $d\mathbf w=\prod_{\ell=1}^k dw_\ell$. Combining \eqref{eq:two-centre-delta-fixed-sum} with the residue-first
convention \eqref{eq:two-centre-residue-first}, after this change of
variables, gives
\begin{align}
 \delta_k(c)
 ={}&\frac1{(2\pi i)^{2k}k!^2}
 \mathcal L^{-1}_{s\to c}
 \Bigg[
 \sum_{a=0}^k\binom{k}{a}s^{-(k+a)}
 \sum_{r=0}^k\binom{k}{r}^{\!2}
 \notag\\[-1mm]
 &\hspace{22mm}\times
 \int_{\mathcal C_x(r)}\int_{\mathcal C_w(r)}
 e^{-sT(\mathbf x)}
 A(\mathbf x,\mathbf w)^a B(\mathbf x,\mathbf w)^k
 \mathcal V(\mathbf x,\mathbf w)
 \,d\mathbf x\,d\mathbf w
 \Bigg],
 \label{eq:two-centre-delta-Laplace-shifted}
\end{align}
where
\begin{equation*}
 \mathcal V(\mathbf x,\mathbf w)
 :=\Delta(\mathbf x)^2\Delta(\mathbf w)^2
   \prod_{j,\ell=1}^k(x_j-w_\ell)
   \prod_{j=1}^k x_j^{-k}
   \prod_{\ell=1}^k(w_\ell-1)^{-k},
\end{equation*}
and
\begin{equation*}
 A(\mathbf x,\mathbf w)
 :=\sum_{j=1}^k\frac1{x_j}+\sum_{\ell=1}^k\frac1{w_\ell},
 \qquad
 B(\mathbf x,\mathbf w)
 :=\sum_{j=1}^k\frac1{x_j-1}+\sum_{\ell=1}^k\frac1{w_\ell-1}.
\end{equation*}
The inverse Laplace transform is understood in the residue-first sense of
\eqref{eq:two-centre-residue-first}; in particular, it already encodes the restriction $c>r$. The powers of $A(\mathbf x,\mathbf w)$ and $B(\mathbf x,\mathbf w)$ above are generated by
\begin{align}
A(\mathbf x,\mathbf w)^a
&=
\left.
\partial_u^a
\exp\!\bigl(uA(\mathbf x,\mathbf w)\bigr)
\right|_{u=0}, \qquad
B(\mathbf x,\mathbf w)^k
&=
\left.
\partial_v^k
\exp\!\bigl(vB(\mathbf x,\mathbf w)\bigr)
\right|_{v=0}.
\label{eq:two-centre-source-generation}
\end{align}
Consider the exponential generating integral
\begin{equation}
\label{eq:two-centre-generating-target}
\frac1{(2\pi i)^{2k}k!^2}
\sum_{r=0}^k\binom{k}{r}^{\!2}
\int_{\mathcal C_x(r)}\int_{\mathcal C_w(r)}
e^{-sT(\mathbf x)+uA(\mathbf x,\mathbf w)+vB(\mathbf x,\mathbf w)}
\mathcal V(\mathbf x,\mathbf w)
\,d\mathbf x\,d\mathbf w.
\end{equation}
We will relate this expression to $D_k(0;s,u,v)$ after applying
$\partial_u^a\partial_v^k$ and evaluating at $u=v=0$, for $0\leq a\leq k$. The reason the moments $X_n$ and $W_n$ arise is visible directly from
the integrand in \eqref{eq:two-centre-generating-target}. Its one-variable
weight factors are
\begin{equation*}
x^{-k}\exp\!\left(-sx+\frac ux+\frac v{x-1}\right)
\qquad\text{and}\qquad
(w-1)^{-k}\exp\!\left(\frac uw+\frac v{w-1}\right).
\end{equation*}
The Laplace variable $s$ appears only in the $x$-weight because the
cutoff depends only on $T(\mathbf x)=\sum_jx_j$. To connect these weights with the moments defined in
\eqref{eq:two-centre-X} and \eqref{eq:two-centre-W}, introduce 
\begin{align}
 d\mu_X^{(\theta)}(z)
 &:=\frac1{2\pi i}
 \left(dz\big|_{C_0}+e^{i\theta}dz\big|_{C_1}\right)
 z^{-k}\exp\!\left(-sz+\frac{u}{z}+\frac{v}{z-1}\right),
 \label{eq:two-centre-muX}
 \\
 d\mu_W^{(\theta)}(z)
 &:=\frac1{2\pi i}
 \left(dz\big|_{C_1}+e^{-i\theta}dz\big|_{C_0}\right)
 (z-1)^{-k}\exp\!\left(\frac{u}{z}+\frac{v}{z-1}\right).
 \label{eq:two-centre-muW}
\end{align}
Then
\begin{equation*}
X_n(\theta;s,u,v)=\int z^n\,d\mu_X^{(\theta)}(z),
\qquad
W_n(\theta;u,v)=\int z^n\,d\mu_W^{(\theta)}(z).
\end{equation*}
Suppressing the
common arguments, so that
\begin{equation*}
 X_n=X_n(\theta;s,u,v),
 \qquad
 W_n=W_n(\theta;u,v),
\end{equation*}
we have
\begingroup
\setlength{\arraycolsep}{3.5pt}
\begin{equation}\label{eq:two-centre-D-matrix}
 D_k(\theta;s,u,v)
 =
 \det\!\begin{pmatrix}
 X_0&X_1&\cdots&X_{k-1}&W_0&W_1&\cdots&W_{k-1}\\
 X_1&X_2&\cdots&X_k&W_1&W_2&\cdots&W_k\\
 \vdots&\vdots&&\vdots&\vdots&\vdots&&\vdots\\
 X_{2k-1}&X_{2k}&\cdots&X_{3k-2}
 &W_{2k-1}&W_{2k}&\cdots&W_{3k-2}
 \end{pmatrix}.
\end{equation}
\endgroup
Therefore the first $k$ columns are generated by the $X$-moments and the
last $k$ columns by the $W$-moments. The above also makes the block Hankel description transparent; reorder the scalar rows in pairs as $(0,k),(1,k+1),\ldots,(k-1,2k-1)$
and reorder the columns so that each $X$-column is placed next to the corresponding $W$-column: 
\begin{equation*}
(X_0,W_0),(X_1,W_1),\ldots,(X_{k-1},W_{k-1}).
\end{equation*}
The row and column reorderings leave the determinant unchanged. Hence
\begin{equation}\label{eq:two-centre-block-Hankel}
 D_k(\theta;s,u,v)
 =\det\left[\mathbf M_{p+q}(\theta;s,u,v)\right]_{p,q=0}^{k-1},
 \qquad
 \mathbf M_n=
 \begin{pmatrix}
 X_n&W_n\\
 X_{n+k}&W_{n+k}
 \end{pmatrix}.
\end{equation}
In particular, the block in position $(p,q)$ depends only on $p+q$, i.e. the same $2 \times 2$ block appears along each block anti-diagonal. We now use a grouped form of Andr\'eief's identity; see
Kuijlaars~\cite[Lemma~2.1]{kuijlaarsMOP}. Let $f_0,\ldots,f_{2k-1}$, $g_0,\ldots,g_{k-1}$, and
$h_0,\ldots,h_{k-1}$ be functions whose products $f_mg_q$ and
$f_mh_q$ are absolutely integrable with respect to $\mu_X$
and $\mu_W$, respectively. Writing
$\mathbf z=(x_1,\ldots,x_k,w_1,\ldots,w_k)$, we have
\begin{align}
&\det\left[
 \int f_m(x)g_q(x)\,d\mu_X(x)
 \ \middle|\
 \int f_m(w)h_q(w)\,d\mu_W(w)
 \right]_{\substack{0\le m\le2k-1\\0\le q\le k-1}}
 \notag\\[-1mm]
&\quad\quad \quad\quad\quad\quad=\frac1{k!^2}
 \int
 \det[f_m(z_j)]_{\substack{0\le m\le2k-1\\1\le j\le2k}}
 \det[g_p(x_q)]_{\substack{0\le p\le k-1\\1\le q\le k}}
 \det[h_p(w_q)]_{\substack{0\le p\le k-1\\1\le q\le k}}
 \notag\\[-1mm]
&\qquad\qquad\qquad\qquad\qquad\times
 \prod_{j=1}^k d\mu_X(x_j)
 \prod_{\ell=1}^k d\mu_W(w_\ell).
 \label{eq:two-centre-Andreief}
\end{align}
Splitting the combined
Vandermonde gives
\begin{align}
\Delta(x_1,\ldots,x_k,w_1,\ldots,w_k)
&=
\Delta(\mathbf x)\Delta(\mathbf w)
\prod_{j,\ell=1}^k(w_\ell-x_j),
\end{align}
and therefore
\begin{align}
\Delta(x_1,\ldots,x_k,w_1,\ldots,w_k)
\Delta(\mathbf x)\Delta(\mathbf w)
&=
(-1)^k
\Delta(\mathbf x)^2\Delta(\mathbf w)^2
\prod_{j,\ell=1}^k(x_j-w_\ell).
\label{eq:two-centre-cross-sign}
\end{align}
In the above, replacing each of the $k^2$ factors $w_\ell-x_j$ by
$-(x_j-w_\ell)$ contributes
$(-1)^{k^2}=(-1)^k$. Next, we aim to recover the integrals in
\eqref{eq:two-centre-delta-Laplace-shifted} from $D_k(0;s,u,v)$.
Apply \eqref{eq:two-centre-Andreief} at $\theta=0$, then
differentiate by $\partial_u^a\partial_v^k$ and evaluate at
$u=v=0$, where $0\leq a\leq k$. The contours are compact and
the integrands are entire in $u,v$, so differentiation may be
taken under the contour integrals. By
\eqref{eq:two-centre-source-generation}, this produces the factor
$A(\mathbf x,\mathbf w)^aB(\mathbf x,\mathbf w)^k$. In the expansion of the product measures, suppose that $p$ of
the $x$-variables are integrated over $C_1$ and $q$ of the
$w$-variables over $C_0$. We show that only the balanced
choices $p=q$ contribute.

After setting $y_\ell=w_\ell-1$, the integrand and contours
are those defining $J_{-s,p,q}^{(a)}(1)$ in
\cite[proof of Lemma~2.6]{kn:bcis26}, with
$\Phi_L(\mathbf x)=e^{LT(\mathbf x)}$.
This function is entire and symmetric in the $x$-variables,
so the shifted pole-count argument there applies and gives
$J_{-s,p,q}^{(a)}(1)=0$ whenever $p\ne q$, for every
$0\leq a\leq k$. Hence only the balanced choices $p=q=r$
survive.

There are $\binom{k}{r}^2$ balanced contour choices. Since the
integrand is symmetric separately in the $x$-variables and
in the $w$-variables, these choices may be relabelled into
$\mathcal C_x(r)$ and $\mathcal C_w(r)$ from
\eqref{eq:two-centre-contour-system}. Using
\eqref{eq:two-centre-cross-sign}, we obtain
\begin{align}
 \left.
 \partial_u^a\partial_v^kD_k(0;s,u,v)
 \right|_{u=v=0}
 ={}&
 \frac{(-1)^k}{(2\pi i)^{2k}k!^2}
 \sum_{r=0}^k\binom{k}{r}^{\!2}
 \int_{\mathcal C_x(r)}\int_{\mathcal C_w(r)}
 e^{-sT(\mathbf x)}
 \notag\\
 &\qquad\qquad\qquad\times
 A(\mathbf x,\mathbf w)^a
 B(\mathbf x,\mathbf w)^k
 \mathcal V(\mathbf x,\mathbf w)
 \,d\mathbf x\,d\mathbf w.
 \label{eq:two-centre-D-derivative-integral}
\end{align}

Write the contour integral in
the $r$-th term as $e^{-rs}Q_{r,a}(s)$, where $Q_{r,a}$ is a
polynomial because the contour poles have finite order. If we put $h=k-r$, the total vanishing order of the Vandermonde
and cross factors at the contour centres is
\begin{equation*}
 Z=2h(h-1)+2r(r-1)+2hr,
\end{equation*}
and the total pole order is at most $2kh+a+k$. Taking a
residue in $2k$ variables therefore gives
\begin{equation*}
 \deg Q_{r,a}
 \leq 2kh+a+k-Z-2k
 =k+a-2r^2.
\end{equation*}
For $r=0$, counting only the $x$-variables gives the stronger
bound
\begin{equation*}
 \deg Q_{0,a}\leq k^2+a-k(k-1)-k=a.
\end{equation*}
A negative degree bound means that the residue vanishes. After multiplication by $s^{-(k+a)}$, only negative powers
of $s$ occur, with exponents at most $-k$ for $r=0$ and
$-2r^2$ for $r\geq1$. Thus
\eqref{eq:two-centre-shifted-Laplace} applies, and the
contributions with $r\geq1$ vanish continuously at $c=r$. Combining \eqref{eq:two-centre-D-derivative-integral} with
\eqref{eq:two-centre-delta-Laplace-shifted} gives
\begin{equation}
 \label{eq:two-centre-before-packing}
 \delta_k(c)
 =
 (-1)^k\mathcal L^{-1}_{s\to c}
 \left[
 \sum_{a=0}^k\binom{k}{a}s^{-(k+a)}
 \left.
 \partial_u^a\partial_v^kD_k(0;s,u,v)
 \right|_{u=v=0}
 \right].
\end{equation}
Here the derivatives in $u,v$ are evaluated at $u=v=0$
before Laplace inversion. Finally, the binomial identity gives
\begin{equation}
 \label{eq:two-centre-binomial-operator}
 \sum_{a=0}^k
 \binom{k}{a}s^{-(k+a)}\partial_u^a
 =
 s^{-k}\left(1+\frac{\partial_u}{s}\right)^k.
\end{equation}
Substituting the above into \eqref{eq:two-centre-before-packing} proves \eqref{eq:two-centre-final-formula}.
